-- ----------------------------
-- Table structure for edu_answer_record
-- ----------------------------
DROP TABLE IF EXISTS `edu_answer_record`;
CREATE TABLE `edu_answer_record`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '主键（雪花算法）',
  `session_id` bigint UNSIGNED NOT NULL COMMENT '评测会话ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '学生用户ID',
  `question_id` bigint UNSIGNED NOT NULL COMMENT '题目ID',
  `knowledge_id` bigint UNSIGNED NOT NULL COMMENT '考查知识点ID（冗余，方便查询）',
  `seq_no` int NOT NULL DEFAULT 1 COMMENT '题目在本次会话中的序号',
  `user_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '用户作答内容',
  `is_correct` tinyint NULL DEFAULT NULL COMMENT '是否正确（0否 1是 NULL未判定-主观题）',
  `score` decimal(5, 2) NULL DEFAULT NULL COMMENT '本题得分',
  `time_spent_ms` int NULL DEFAULT NULL COMMENT '作答耗时（毫秒）',
  `confidence` tinyint NULL DEFAULT NULL COMMENT '用户自评置信度（1-5，可选）',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标志（0正常 1删除）',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_session`(`session_id`) USING BTREE,
  INDEX `idx_user_knowledge`(`user_id`, `knowledge_id`) USING BTREE,
  INDEX `fk_ar_question`(`question_id`) USING BTREE,
  INDEX `fk_ar_knowledge`(`knowledge_id`) USING BTREE,
  CONSTRAINT `fk_ar_knowledge` FOREIGN KEY (`knowledge_id`) REFERENCES `edu_knowledge_node` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ar_question` FOREIGN KEY (`question_id`) REFERENCES `edu_question` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ar_session` FOREIGN KEY (`session_id`) REFERENCES `edu_assessment_session` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ar_user` FOREIGN KEY (`user_id`) REFERENCES `sl_sys_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '答题记录表' ROW_FORMAT = Dynamic;

