-- ----------------------------
-- Table structure for edu_assessment_session
-- ----------------------------
DROP TABLE IF EXISTS `edu_assessment_session`;
CREATE TABLE `edu_assessment_session`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '主键（雪花算法）',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '学生用户ID',
  `subject_id` bigint UNSIGNED NOT NULL COMMENT '评测学科ID',
  `session_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'entry' COMMENT '类型（entry入学评测/scan漏洞扫描/practice练习）',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT '状态（pending/ongoing/completed/aborted）',
  `total_questions` int NOT NULL DEFAULT 0 COMMENT '计划题目数量',
  `answered_count` int NOT NULL DEFAULT 0 COMMENT '已作答题目数量',
  `correct_count` int NOT NULL DEFAULT 0 COMMENT '答对数量',
  `score` decimal(5, 2) NULL DEFAULT NULL COMMENT '本次评测得分（百分制）',
  `started_at` datetime(3) NULL DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime(3) NULL DEFAULT NULL COMMENT '完成时间',
  `config_json` json NULL COMMENT '评测配置参数（难度范围/知识点范围等）',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标志（0正常 1删除）',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_subject`(`user_id`, `subject_id`, `status`) USING BTREE,
  INDEX `fk_as_subject`(`subject_id`) USING BTREE,
  CONSTRAINT `fk_as_subject` FOREIGN KEY (`subject_id`) REFERENCES `edu_subject` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_as_user` FOREIGN KEY (`user_id`) REFERENCES `sl_sys_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '评测会话表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of edu_assessment_session
-- ----------------------------

-- ----------------------------
-- Table structure for edu_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `edu_chat_message`;
CREATE TABLE `edu_chat_message`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '雪花ID',
  `session_id` bigint UNSIGNED NOT NULL COMMENT '关联会话ID',
  `role` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色: user=学生 assistant=AI',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `metadata_json` json NULL COMMENT '附加数据（相似题列表、关联知识点等）',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标志（0正常 1删除）',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建用户ID',
