-- ----------------------------
-- Table structure for edu_chat_session
-- ----------------------------
DROP TABLE IF EXISTS `edu_chat_session`;
CREATE TABLE `edu_chat_session`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '雪花ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户ID',
  `subject_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '关联学科（可空，虚拟实验时必填）',
  `session_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'qa' COMMENT '会话类型: qa=智能答疑, experiment=虚拟实验',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会话标题（首条消息截取前50字）',
  `message_count` int NOT NULL DEFAULT 0 COMMENT '消息总数',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0正常 1删除',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建用户ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改用户ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_type`(`user_id`, `session_type`, `del_flag`) USING BTREE,
  INDEX `idx_updated`(`updated_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI辅导聊天会话' ROW_FORMAT = Dynamic;

