-- ----------------------------
-- Table structure for edu_error_analysis
-- ----------------------------
DROP TABLE IF EXISTS `edu_error_analysis`;
CREATE TABLE `edu_error_analysis`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '主键（雪花算法）',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '学生用户ID',
  `answer_id` bigint UNSIGNED NOT NULL COMMENT '关联的答题记录ID',
  `question_id` bigint UNSIGNED NOT NULL COMMENT '题目ID（冗余）',
  `knowledge_id` bigint UNSIGNED NOT NULL COMMENT '知识点ID（冗余）',
  `error_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '错误类型（careless粗心/concept概念模糊/method方法缺失/prerequisite前置缺失/unknown未知）',
  `error_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI分析的详细错因描述',
  `missing_prereq_ids` json NULL COMMENT '缺失的前置知识点ID列表（JSON字符串数组）',
  `suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI给出的针对性改进建议',
  `ai_raw_response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI原始返回内容（调试用）',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标志（0正常 1删除）',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_knowledge`(`user_id`, `knowledge_id`) USING BTREE,
  INDEX `idx_error_type`(`error_type`) USING BTREE,
  INDEX `fk_ea_answer`(`answer_id`) USING BTREE,
  INDEX `fk_ea_question`(`question_id`) USING BTREE,
  INDEX `fk_ea_knowledge`(`knowledge_id`) USING BTREE,
  CONSTRAINT `fk_ea_answer` FOREIGN KEY (`answer_id`) REFERENCES `edu_answer_record` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ea_knowledge` FOREIGN KEY (`knowledge_id`) REFERENCES `edu_knowledge_node` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ea_question` FOREIGN KEY (`question_id`) REFERENCES `edu_question` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ea_user` FOREIGN KEY (`user_id`) REFERENCES `sl_sys_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '错因分析记录表' ROW_FORMAT = Dynamic;

