-- ----------------------------
-- Table structure for edu_knowledge_node
-- ----------------------------
DROP TABLE IF EXISTS `edu_knowledge_node`;
CREATE TABLE `edu_knowledge_node`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '主键（雪花算法）',
  `subject_id` bigint UNSIGNED NOT NULL COMMENT '所属学科ID',
  `parent_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '父节点ID（NULL为根节点）',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '知识点名称',
  `level` tinyint NOT NULL DEFAULT 1 COMMENT '层级（1章 2节 3知识点）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '同级排序',
  `difficulty` tinyint NOT NULL DEFAULT 3 COMMENT '默认难度（1-5）',
  `prerequisite_ids` json NULL COMMENT '前置知识点ID列表（JSON字符串数组）',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标志（0正常 1删除）',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_subject_parent`(`subject_id`, `parent_id`) USING BTREE,
  INDEX `idx_parent`(`parent_id`) USING BTREE,
  CONSTRAINT `fk_kn_subject` FOREIGN KEY (`subject_id`) REFERENCES `edu_subject` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识点树形节点表' ROW_FORMAT = Dynamic;

