-- Records of edu_knowledge_node
-- ----------------------------

-- ----------------------------
-- Table structure for edu_learning_plan
-- ----------------------------
DROP TABLE IF EXISTS `edu_learning_plan`;
CREATE TABLE `edu_learning_plan`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '主键（雪花算法）',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '学生用户ID',
  `subject_id` bigint UNSIGNED NOT NULL COMMENT '学科ID',
  `plan_date` date NOT NULL COMMENT '计划日期（YYYY-MM-DD）',
  `plan_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'daily' COMMENT '计划类型（daily今日计划）',
  `recommended_nodes_json` json NULL COMMENT '推荐知识点列表JSON [{knowledge_id,name,reason,priority,mastery_score,comprehension_score,memory_score,application_score,prerequisite_met,suggested_question_count}]',
  `ai_recommendation_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI生成的学习建议全文（纯文本，含学习资源推荐说明）',
  `weak_comprehension_json` json NULL COMMENT '理解薄弱知识点快照 [{id,name,score}]',
  `weak_memory_json` json NULL COMMENT '记忆薄弱知识点快照 [{id,name,score}]',
  `weak_application_json` json NULL COMMENT '应用薄弱知识点快照 [{id,name,score}]',
  `is_stale` tinyint NOT NULL DEFAULT 0 COMMENT '是否已过期（0有效 1强制重新生成）',
  `generated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'AI生成时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标志（0正常 1删除）',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_subject_date`(`user_id`, `subject_id`, `plan_date`, `plan_type`) USING BTREE,
  INDEX `idx_user_date`(`user_id`, `plan_date`) USING BTREE,
  INDEX `fk_lp_subject`(`subject_id`) USING BTREE,
  CONSTRAINT `fk_lp_subject` FOREIGN KEY (`subject_id`) REFERENCES `edu_subject` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_lp_user` FOREIGN KEY (`user_id`) REFERENCES `sl_sys_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI学习计划缓存表' ROW_FORMAT = Dynamic;

