-- ----------------------------
-- Table structure for edu_oral_record
-- ----------------------------
DROP TABLE IF EXISTS `edu_oral_record`;
CREATE TABLE `edu_oral_record`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '雪花ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户ID',
  `subject_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '关联学科',
  `original_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原文（朗读材料）',
  `transcribed_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学生转录内容（Web Speech API结果）',
  `accuracy_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '准确度得分（0-100）',
  `fluency_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '流利度得分（0-100）',
  `completeness_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '完整度得分（0-100）',
  `overall_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '综合得分（0-100）',
  `ai_feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'AI详细反馈文本',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0正常 1删除',
  `created_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建用户ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL COMMENT '修改用户ID',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id`, `del_flag`, `created_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '口语评测记录' ROW_FORMAT = Dynamic;

