INSERT INTO `edu_error_analysis` VALUES (344515820216520704, 1, 344515584337252352, 3000000000000005, 2000000000000007, 'careless', '学生可能已经知道如何计算导数，但在计算过程中犯了粗心错误。', NULL, '建议学生在计算时更加细心，检查每一步的计算过程，避免因粗心大意导致的错误。', '```json\n{\n  \"error_type\": \"careless\",\n  \"detail\": \"学生可能已经知道如何计算导数，但在计算过程中犯了粗心错误。\",\n  \"suggestion\": \"建议学生在计算时更加细心，检查每一步的计算过程，避免因粗心大意导致的错误。\"\n}\n```', 0, 1, '2026-08-09 00:22:53.436', NULL, '2026-08-09 00:22:53.436', NULL);
INSERT INTO `edu_error_analysis` VALUES (344515828424773632, 1, 344515628683628544, 3000000000000003, 2000000000000012, 'careless', '学生已知等差数列的通项公式，但计算过程中出现错误，导致答案错误。', NULL, '在计算过程中仔细检查每一步，确保计算准确无误。', '```json\n{\n  \"error_type\": \"careless\",\n  \"detail\": \"学生已知等差数列的通项公式，但计算过程中出现错误，导致答案错误。\",\n  \"suggestion\": \"在计算过程中仔细检查每一步，确保计算准确无误。\"\n}\n```', 0, 1, '2026-08-09 00:22:55.393', NULL, '2026-08-09 00:22:55.393', NULL);
INSERT INTO `edu_error_analysis` VALUES (344515841934626816, 1, 344515715933540352, 3000000000000007, 2000000000000014, 'careless', '学生虽然知道等比数列的通项公式，但在计算过程中出现了错误，导致最终答案错误。', NULL, '建议学生在计算时仔细检查每一步，尤其是在进行乘法运算时，以避免因粗心大意导致的错误。', '```json\n{\n  \"error_type\": \"careless\",\n  \"detail\": \"学生虽然知道等比数列的通项公式，但在计算过程中出现了错误，导致最终答案错误。\",\n  \"suggestion\": \"建议学生在计算时仔细检查每一步，尤其是在进行乘法运算时，以避免因粗心大意导致的错误。\"\n}\n```', 0, 1, '2026-08-09 00:22:58.614', NULL, '2026-08-09 00:22:58.614', NULL);
INSERT INTO `edu_error_analysis` VALUES (345022593671237632, 1, 345021932867031040, 3210000000000006, 2210000000000004, 'concept', '学生对通假字的概念理解不准确，未能正确识别\'惠\'字在古文中的通假字是\'慧\'。', NULL, '建议学生加强对通假字的学习，理解其定义和常见通假字，并多进行相关练习，提高对古文中通假字的认识。', '```json\n{\n  \"error_type\": \"concept\",\n  \"detail\": \"学生对通假字的概念理解不准确，未能正确识别\'惠\'字在古文中的通假字是\'慧\'。\",\n  \"suggestion\": \"建议学生加强对通假字的学习，理解其定义和常见通假字，并多进行相关练习，提高对古文中通假字的认识。\"\n}\n```', 0, 1, '2026-08-10 09:56:37.071', NULL, '2026-08-10 09:56:37.071', NULL);
INSERT INTO `edu_error_analysis` VALUES (345022607227228160, 1, 345022061929959424, 3210000000000002, 2210000000000004, 'careless', '学生在短时间内选择了错误答案，可能是由于匆忙或注意力不集中导致的。', NULL, '建议学生在考试中放慢速度，仔细阅读题目和选项，避免因粗心大意而犯错。', '```json\n{\n  \"error_type\": \"careless\",\n  \"detail\": \"学生在短时间内选择了错误答案，可能是由于匆忙或注意力不集中导致的。\",\n  \"suggestion\": \"建议学生在考试中放慢速度，仔细阅读题目和选项，避免因粗心大意而犯错。\"\n}\n```', 0, 1, '2026-08-10 09:56:40.304', NULL, '2026-08-10 09:56:40.304', NULL);
INSERT INTO `edu_error_analysis` VALUES (345022619361349632, 1, 345022145107202048, 3210000000000009, 2210000000000006, 'concept', '学生对判断句与省略句的概念理解不准确，误将判断句当作疑问句。', NULL, '建议学生加强对判断句和疑问句的区分，通过练习和阅读不同类型的句子来加深理解。', '```json\n{\n  \"error_type\": \"concept\",\n  \"detail\": \"学生对判断句与省略句的概念理解不准确，误将判断句当作疑问句。\",\n  \"suggestion\": \"建议学生加强对判断句和疑问句的区分，通过练习和阅读不同类型的句子来加深理解。\"\n}\n```', 0, 1, '2026-08-10 09:56:43.197', NULL, '2026-08-10 09:56:43.197', NULL);
INSERT INTO `edu_error_analysis` VALUES (345022626336477184, 1, 345022326213054464, 3210000000000008, 2210000000000005, 'careless', '学生在极短时间内选择了错误答案，可能是由于匆忙或注意力不集中导致的。', NULL, '建议学生在考试中放慢速度，仔细审题，并检查答案是否与题意相符。', '```json\n{\n  \"error_type\": \"careless\",\n  \"detail\": \"学生在极短时间内选择了错误答案，可能是由于匆忙或注意力不集中导致的。\",\n  \"suggestion\": \"建议学生在考试中放慢速度，仔细审题，并检查答案是否与题意相符。\"\n}\n```', 0, 1, '2026-08-10 09:56:44.862', NULL, '2026-08-10 09:56:44.862', NULL);
INSERT INTO `edu_error_analysis` VALUES (345024463525515264, 1, 345024094963634176, 3310000000000008, 2310000000000006, 'concept', '学生对平仄规律中的平声字概念理解不准确，误以为入声字属于平声。', NULL, '建议学生复习平仄规律，明确平声字包括阴平和阳平，并加强相关例句的练习，加深对概念的理解。', '```json\n{\n  \"error_type\": \"concept\",\n  \"detail\": \"学生对平仄规律中的平声字概念理解不准确，误以为入声字属于平声。\",\n  \"suggestion\": \"建议学生复习平仄规律，明确平声字包括阴平和阳平，并加强相关例句的练习，加深对概念的理解。\"\n}\n```', 0, 1, '2026-08-10 10:04:02.904', NULL, '2026-08-10 10:04:02.904', NULL);
INSERT INTO `edu_error_analysis` VALUES (345024477035368448, 1, 345024210076307456, 3310000000000003, 2310000000000006, 'concept', '学生对律诗的基本格律要求理解不准确，误以为律诗只有四句。', NULL, '建议学生加强对平仄规律的学习，特别是对律诗格律的具体要求进行深入理解。可以通过阅读相关文学作品和格律知识，加深对律诗结构的认识。', '```json\n{\n  \"error_type\": \"concept\",\n  \"detail\": \"学生对律诗的基本格律要求理解不准确，误以为律诗只有四句。\",\n  \"suggestion\": \"建议学生加强对平仄规律的学习，特别是对律诗格律的具体要求进行深入理解。可以通过阅读相关文学作品和格律知识，加深对律诗结构的认识。\"\n}\n```', 0, 1, '2026-08-10 10:04:06.124', NULL, '2026-08-10 10:04:06.124', NULL);
INSERT INTO `edu_error_analysis` VALUES (345024490759131136, 1, 345024280955850752, 3310000000000009, 2310000000000006, 'concept', '学生对五言律诗的定义和结构理解不准确，未能正确识别五言律诗每句的字数。', NULL, '建议学生复习五言律诗的相关知识，理解其结构特点，并加强记忆五言律诗每句的字数。', '```json\n{\n  \"error_type\": \"concept\",\n  \"detail\": \"学生对五言律诗的定义和结构理解不准确，未能正确识别五言律诗每句的字数。\",\n  \"suggestion\": \"建议学生复习五言律诗的相关知识，理解其结构特点，并加强记忆五言律诗每句的字数。\"\n}\n```', 0, 1, '2026-08-10 10:04:09.398', NULL, '2026-08-10 10:04:09.398', NULL);
INSERT INTO `edu_error_analysis` VALUES (345024513341263872, 1, 345024317186248704, 3310000000000002, 2310000000000005, 'concept', '学生可能对情感表达手法中的夸张和对偶的概念理解不够清晰，未能正确识别出题目中的对偶和夸张手法。', NULL, '建议学生加强对文学表现手法的理解和记忆，特别是夸张和对偶这两种手法，通过阅读和分析更多文学作品来提高识别能力。', '```json\n{\n  \"error_type\": \"concept\",\n  \"detail\": \"学生可能对情感表达手法中的夸张和对偶的概念理解不够清晰，未能正确识别出题目中的对偶和夸张手法。\",\n  \"suggestion\": \"建议学生加强对文学表现手法的理解和记忆，特别是夸张和对偶这两种手法，通过阅读和分析更多文学作品来提高识别能力。\"\n}\n```', 0, 1, '2026-08-10 10:04:14.781', NULL, '2026-08-10 10:04:14.781', NULL);
