INSERT INTO `edu_learning_plan` VALUES (344516785732718592, 1, 1000000000000001, '2026-08-09', 'daily', '[{\"name\": \"函数的单调性\", \"reason\": \"掌握度 0分，需要加强\", \"priority\": 1, \"knowledge_id\": \"2000000000000006\", \"memory_score\": 0, \"mastery_score\": 0, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"导数的定义\", \"reason\": \"掌握度 0分，需要加强\", \"priority\": 2, \"knowledge_id\": \"2000000000000007\", \"memory_score\": 0, \"mastery_score\": 0, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"等差数列通项公式\", \"reason\": \"掌握度 0分，需要加强\", \"priority\": 3, \"knowledge_id\": \"2000000000000012\", \"memory_score\": 0, \"mastery_score\": 0, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"等比数列通项公式\", \"reason\": \"掌握度 0分，需要加强\", \"priority\": 4, \"knowledge_id\": \"2000000000000014\", \"memory_score\": 0, \"mastery_score\": 0, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"函数的定义域\", \"reason\": \"掌握度 10分，需要加强\", \"priority\": 5, \"knowledge_id\": \"2000000000000004\", \"memory_score\": 0, \"mastery_score\": 10, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}]', '📅 今日学习重点：集中攻克函数的单调性、导数的定义、等差数列和等比数列通项公式，同时巩固函数的定义域。\n\n📌 各知识点建议：\n1. 函数的单调性：首先，仔细回顾函数单调性的定义，理解其几何意义。然后，通过绘制函数图像，尝试发现不同函数的单调区间，并总结规律。\n2. 导数的定义：深入理解导数的概念，特别是极限的思想。尝试用导数的定义来计算一些简单函数的导数，如一次函数、二次函数等。\n3. 等差数列通项公式：回顾等差数列的定义，通过实例理解通项公式的来源。然后，尝试自己推导通项公式，并验证其正确性。\n4. 等比数列通项公式：同样，回顾等比数列的定义，通过实例理解通项公式的来源。自己推导通项公式，并尝试解决一些相关的问题。\n5. 函数的定义域：回顾函数定义域的概念，通过具体例子分析不同函数的定义域。尝试找出给定函数的定义域，并解释原因。\n\n📚 学习资源推荐：\n- 函数的单调性：可以尝试寻找一些关于函数图像的书籍或在线资源，通过图像直观地理解单调性。\n- 导数的定义：推荐一些极限和导数的入门书籍，或者在线视频教程。\n- 等差数列和等比数列：可以通过一些数列的习题集来练习，特别是那些包含推导和证明的题目。\n- 函数的定义域：可以查看一些关于函数概念的教材，特别是那些包含大量例题和习题的部分。\n\n💪 今日目标：通过今日的学习，希望你能对上述知识点有更深入的理解，并能够独立解决一些相关的问题。加油！', '[{\"id\": \"2000000000000006\", \"name\": \"函数的单调性\", \"score\": 0}, {\"id\": \"2000000000000007\", \"name\": \"导数的定义\", \"score\": 0}, {\"id\": \"2000000000000012\", \"name\": \"等差数列通项公式\", \"score\": 0}, {\"id\": \"2000000000000014\", \"name\": \"等比数列通项公式\", \"score\": 0}, {\"id\": \"2000000000000004\", \"name\": \"函数的定义域\", \"score\": 0}]', '[{\"id\": \"2000000000000006\", \"name\": \"函数的单调性\", \"score\": 0}, {\"id\": \"2000000000000007\", \"name\": \"导数的定义\", \"score\": 0}, {\"id\": \"2000000000000012\", \"name\": \"等差数列通项公式\", \"score\": 0}, {\"id\": \"2000000000000014\", \"name\": \"等比数列通项公式\", \"score\": 0}, {\"id\": \"2000000000000004\", \"name\": \"函数的定义域\", \"score\": 0}]', '[{\"id\": \"2000000000000006\", \"name\": \"函数的单调性\", \"score\": 0}, {\"id\": \"2000000000000007\", \"name\": \"导数的定义\", \"score\": 0}, {\"id\": \"2000000000000012\", \"name\": \"等差数列通项公式\", \"score\": 0}, {\"id\": \"2000000000000014\", \"name\": \"等比数列通项公式\", \"score\": 0}, {\"id\": \"2000000000000004\", \"name\": \"函数的定义域\", \"score\": 0}]', 0, '2026-08-09 00:26:43.648', 0, 1, '2026-08-09 00:26:43.648', NULL, '2026-08-09 00:26:43.648', NULL);
INSERT INTO `edu_learning_plan` VALUES (344541776490663936, 1, 1100000000000002, '2026-08-09', 'daily', '[{\"name\": \"竖式计算\", \"reason\": \"掌握度 10分，需要加强\", \"priority\": 1, \"knowledge_id\": \"2120000000000005\", \"memory_score\": 0, \"mastery_score\": 10, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}]', '📅 今日学习重点：针对竖式计算中的概念模糊问题，进行专项强化训练。\n\n📌 各知识点建议：\n- 问题诊断：你对竖式计算的概念理解不够清晰，导致应用时出现错误。\n- 学法建议：首先回顾竖式计算的原理，然后通过大量练习来提高熟练度。\n\n📚 学习资源推荐：\n- 练习方向：选择一些包含多位数乘除法的竖式计算题目，如“123 × 45”或“789 ÷ 21”。\n- 例题类型：尝试解决一些应用题，如“小明有123个苹果，平均分给45个小朋友，每人能分到多少个苹果？”\n\n💪 今日目标：通过今日的学习，能够熟练完成竖式计算，并提高对概念的理解。', '[{\"id\": \"2120000000000005\", \"name\": \"竖式计算\", \"score\": 0}]', '[{\"id\": \"2120000000000005\", \"name\": \"竖式计算\", \"score\": 0}]', '[{\"id\": \"2120000000000005\", \"name\": \"竖式计算\", \"score\": 0}]', 0, '2026-08-09 02:06:02.238', 0, 1, '2026-08-09 02:06:02.238', NULL, '2026-08-09 02:06:02.238', NULL);
INSERT INTO `edu_learning_plan` VALUES (344541871084802048, 1, 1100000000000001, '2026-08-09', 'daily', '[{\"name\": \"笔画笔顺\", \"reason\": \"掌握度 0分，需要加强\", \"priority\": 1, \"knowledge_id\": \"2110000000000006\", \"memory_score\": 0, \"mastery_score\": 0, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"四声声调\", \"reason\": \"掌握度 10分，需要加强\", \"priority\": 2, \"knowledge_id\": \"2110000000000005\", \"memory_score\": 0, \"mastery_score\": 10, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}]', '📅 今日学习重点：攻克笔画笔顺和四声声调，提升语文基础能力。\n\n📌 各知识点建议：\n1. 笔画笔顺：首先，仔细观察例字，分析其笔画顺序；其次，通过练习，加强记忆，如每天练习5个新字，并复习旧字。\n2. 四声声调：理解声调的发音特点，如第一声高而平，第二声先升后降等；通过朗读练习，提高对声调的敏感度。\n\n📚 学习资源推荐：\n- 练习笔画笔顺的练习册，如《汉字笔画练习册》；\n- 朗读练习，选择不同声调的课文进行朗读，如《声调练习篇》。\n\n💪 今日目标：掌握笔画笔顺和四声声调的基础知识，为今后的语文学习打下坚实基础。加油，你一定可以做到！', '[{\"id\": \"2110000000000006\", \"name\": \"笔画笔顺\", \"score\": 0}, {\"id\": \"2110000000000005\", \"name\": \"四声声调\", \"score\": 0}]', '[{\"id\": \"2110000000000006\", \"name\": \"笔画笔顺\", \"score\": 0}, {\"id\": \"2110000000000005\", \"name\": \"四声声调\", \"score\": 0}]', '[{\"id\": \"2110000000000006\", \"name\": \"笔画笔顺\", \"score\": 0}, {\"id\": \"2110000000000005\", \"name\": \"四声声调\", \"score\": 0}]', 0, '2026-08-09 02:06:24.793', 0, 1, '2026-08-09 02:06:24.793', NULL, '2026-08-09 02:06:24.793', NULL);
INSERT INTO `edu_learning_plan` VALUES (344541984968544256, 1, 1100000000000003, '2026-08-09', 'daily', '[{\"name\": \"大小写字母\", \"reason\": \"掌握度 17分，需要加强\", \"priority\": 1, \"knowledge_id\": \"2130000000000004\", \"memory_score\": 0, \"mastery_score\": 17, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"字母发音规则\", \"reason\": \"掌握度 25分，需要加强\", \"priority\": 2, \"knowledge_id\": \"2130000000000005\", \"memory_score\": 0, \"mastery_score\": 25, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"数字与颜色词汇\", \"reason\": \"掌握度 30分，需要加强\", \"priority\": 3, \"knowledge_id\": \"2130000000000006\", \"memory_score\": 0, \"mastery_score\": 30, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}]', '📅 今日学习重点：巩固字母大小写和发音规则，拓展数字与颜色词汇。\n\n📌 各知识点建议：\n1. **大小写字母**：首先，回顾大小写字母的形状和发音区别，通过制作卡片进行记忆练习；其次，尝试编写句子，确保能正确使用大小写字母。\n2. **字母发音规则**：理解英文字母的发音规则，可以通过听读练习来加深记忆；接着，尝试拼读新的单词，检验对规则的应用。\n3. **数字与颜色词汇**：记忆数字和颜色的英文表达，通过看图匹配或填空练习来巩固。\n\n📚 学习资源推荐：\n- 制作字母大小写卡片，进行自我测试。\n- 收集包含字母发音规则的英语儿歌或动画视频。\n- 选择包含数字和颜色词汇的英语绘本或故事进行阅读。\n\n💪 今日目标：通过今日的学习，希望你能掌握大小写字母的正确使用，理解并应用字母发音规则，同时拓展并记忆数字与颜色词汇。加油！', '[{\"id\": \"2130000000000004\", \"name\": \"大小写字母\", \"score\": 0}, {\"id\": \"2130000000000005\", \"name\": \"字母发音规则\", \"score\": 0}, {\"id\": \"2130000000000006\", \"name\": \"数字与颜色词汇\", \"score\": 0}]', '[{\"id\": \"2130000000000004\", \"name\": \"大小写字母\", \"score\": 0}, {\"id\": \"2130000000000005\", \"name\": \"字母发音规则\", \"score\": 0}, {\"id\": \"2130000000000006\", \"name\": \"数字与颜色词汇\", \"score\": 0}]', '[{\"id\": \"2130000000000004\", \"name\": \"大小写字母\", \"score\": 0}, {\"id\": \"2130000000000005\", \"name\": \"字母发音规则\", \"score\": 0}, {\"id\": \"2130000000000006\", \"name\": \"数字与颜色词汇\", \"score\": 0}]', 0, '2026-08-09 02:06:51.945', 0, 1, '2026-08-09 02:06:51.945', NULL, '2026-08-09 02:06:51.945', NULL);
INSERT INTO `edu_learning_plan` VALUES (344909757997518848, 1, 1100000000000001, '2026-08-10', 'daily', '[{\"name\": \"笔画笔顺\", \"reason\": \"掌握度 15分，需要加强\", \"priority\": 1, \"knowledge_id\": \"2110000000000006\", \"memory_score\": 0, \"mastery_score\": 15, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"四声声调\", \"reason\": \"掌握度 17分，需要加强\", \"priority\": 2, \"knowledge_id\": \"2110000000000005\", \"memory_score\": 0, \"mastery_score\": 17, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"声母韵母\", \"reason\": \"掌握度 27分，需要加强\", \"priority\": 3, \"knowledge_id\": \"2110000000000004\", \"memory_score\": 0, \"mastery_score\": 27, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}]', '📅 今日学习重点：强化基础语音知识，提升对声母韵母的理解和应用能力。\n\n📌 各知识点建议：\n1. 笔画笔顺：通过练习笔顺口诀，加强记忆；对比分析不同笔画的书写顺序，加深理解。\n2. 四声声调：制作声调卡片，反复练习发音；对比四声，区分声调的细微差别。\n3. 声母韵母：分类记忆声母和韵母的发音特点，结合拼音练习，提高拼读能力。\n\n📚 学习资源推荐：\n- 练习笔画笔顺的练习册，例题包括常见的汉字笔画顺序；\n- 声调卡片，帮助记忆和区分四声；\n- 拼音练习册，包含声母韵母的拼读练习。\n\n💪 今日目标：通过今日学习，能够熟练掌握笔画笔顺，正确区分四声声调，并能准确拼读声母韵母组合的拼音。', '[{\"id\": \"2110000000000006\", \"name\": \"笔画笔顺\", \"score\": 0}, {\"id\": \"2110000000000005\", \"name\": \"四声声调\", \"score\": 0}, {\"id\": \"2110000000000004\", \"name\": \"声母韵母\", \"score\": 0}]', '[{\"id\": \"2110000000000006\", \"name\": \"笔画笔顺\", \"score\": 0}, {\"id\": \"2110000000000005\", \"name\": \"四声声调\", \"score\": 0}, {\"id\": \"2110000000000004\", \"name\": \"声母韵母\", \"score\": 0}]', '[{\"id\": \"2110000000000006\", \"name\": \"笔画笔顺\", \"score\": 0}, {\"id\": \"2110000000000005\", \"name\": \"四声声调\", \"score\": 0}, {\"id\": \"2110000000000004\", \"name\": \"声母韵母\", \"score\": 0}]', 0, '2026-08-10 02:28:15.286', 0, 1, '2026-08-10 02:28:15.286', NULL, '2026-08-10 02:28:15.286', NULL);
INSERT INTO `edu_learning_plan` VALUES (345024678626201600, 1, 1300000000000001, '2026-08-10', 'daily', '[{\"name\": \"平仄规律\", \"reason\": \"掌握度 0分，需要加强\", \"priority\": 1, \"knowledge_id\": \"2310000000000006\", \"memory_score\": 0, \"mastery_score\": 0, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"情感表达手法\", \"reason\": \"掌握度 12分，需要加强\", \"priority\": 2, \"knowledge_id\": \"2310000000000005\", \"memory_score\": 0, \"mastery_score\": 12, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}, {\"name\": \"常见意象含义\", \"reason\": \"掌握度 25分，需要加强\", \"priority\": 3, \"knowledge_id\": \"2310000000000004\", \"memory_score\": 0, \"mastery_score\": 25, \"prerequisite_met\": true, \"application_score\": 0, \"comprehension_score\": 0, \"suggested_question_count\": 3}]', '📅 今日学习重点：集中攻克平仄规律和情感表达手法，提升常见意象含义理解。\n\n📌 各知识点建议：\n1. 平仄规律：首先，你需要理解平仄的基本概念，比如平声和仄声的区别，它们在诗歌中的作用。然后，可以通过制作表格来记忆平仄的规律，多读古诗词，感受平仄带来的韵律美。\n\n2. 情感表达手法：分析近期错误，概念模糊是关键。建议你先梳理情感表达手法的种类，如直接抒情、间接抒情等，然后结合具体诗词，分析作者如何运用这些手法。\n\n3. 常见意象含义：目前你对意象的理解还不够深入。建议你通过查阅资料，了解常见的意象及其象征意义，同时，在阅读诗词时，尝试找出并分析意象。\n\n📚 学习资源推荐：可以找一些诗词鉴赏书籍，如《唐诗鉴赏词典》等，通过阅读和解读，加深对平仄规律和情感表达手法的理解。\n\n💪 今日目标：通过今日的学习，希望你能对平仄规律和情感表达手法有初步的认识，并在阅读诗词时能运用所学知识，提升对常见意象含义的把握。加油！', '[{\"id\": \"2310000000000006\", \"name\": \"平仄规律\", \"score\": 0}, {\"id\": \"2310000000000005\", \"name\": \"情感表达手法\", \"score\": 0}, {\"id\": \"2310000000000004\", \"name\": \"常见意象含义\", \"score\": 0}]', '[{\"id\": \"2310000000000006\", \"name\": \"平仄规律\", \"score\": 0}, {\"id\": \"2310000000000005\", \"name\": \"情感表达手法\", \"score\": 0}, {\"id\": \"2310000000000004\", \"name\": \"常见意象含义\", \"score\": 0}]', '[{\"id\": \"2310000000000006\", \"name\": \"平仄规律\", \"score\": 0}, {\"id\": \"2310000000000005\", \"name\": \"情感表达手法\", \"score\": 0}, {\"id\": \"2310000000000004\", \"name\": \"常见意象含义\", \"score\": 0}]', 0, '2026-08-10 10:04:54.191', 0, 1, '2026-08-10 10:04:54.191', NULL, '2026-08-10 10:04:54.191', NULL);
INSERT INTO `edu_oral_record` VALUES (345026026679701504, 1, NULL, 'Dear auntie, thanks very much! .Well, thanks very much for joining us here at RealmadridTV and best of luck for the season. ...', 'Dear auntie, thanks very much! .Well, thanks very much for join us here at RealmadridTV and of luck for', 85.00, 90.00, 80.00, 85.00, '准确度方面，\'join\'应为\'joining\'，\'of\'应为\'for\'。流利度较好，但可适当调整语速。完整度略低，建议检查并补充遗漏的单词。', 0, NULL, '2026-08-10 10:10:15.608', NULL, '2026-08-10 10:10:15.608', NULL);
INSERT INTO `edu_question` VALUES (3110000000000001, 1100000000000001, 2110000000000004, 'single', 1, '下列哪个是声母？', '[{\"key\": \"A\", \"text\": \"a\"}, {\"key\": \"B\", \"text\": \"b\"}, {\"key\": \"C\", \"text\": \"e\"}, {\"key\": \"D\", \"text\": \"o\"}]', 'B', '声母是辅音，b/p/m/f等是声母；a/e/o等是韵母', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.685', NULL, '2026-08-09 01:14:58.685', NULL);
INSERT INTO `edu_question` VALUES (3110000000000002, 1100000000000001, 2110000000000004, 'single', 1, '\"zh、ch、sh\"属于哪类声母？', '[{\"key\": \"A\", \"text\": \"唇齿音\"}, {\"key\": \"B\", \"text\": \"舌尖音\"}, {\"key\": \"C\", \"text\": \"翘舌音\"}, {\"key\": \"D\", \"text\": \"舌根音\"}]', 'C', 'zh、ch、sh是翘舌音（卷舌音）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.685', NULL, '2026-08-09 01:14:58.685', NULL);
INSERT INTO `edu_question` VALUES (3110000000000003, 1100000000000001, 2110000000000005, 'single', 1, '汉字\"妈\"的声调是第几声？', '[{\"key\": \"A\", \"text\": \"第一声\"}, {\"key\": \"B\", \"text\": \"第二声\"}, {\"key\": \"C\", \"text\": \"第三声\"}, {\"key\": \"D\", \"text\": \"第四声\"}]', 'A', '\"妈\"读mā，是阴平，第一声', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.685', NULL, '2026-08-09 01:14:58.685', NULL);
INSERT INTO `edu_question` VALUES (3110000000000004, 1100000000000001, 2110000000000006, 'single', 2, '\"水\"字共有几画？', '[{\"key\": \"A\", \"text\": \"3画\"}, {\"key\": \"B\", \"text\": \"4画\"}, {\"key\": \"C\", \"text\": \"5画\"}, {\"key\": \"D\", \"text\": \"6画\"}]', 'B', '\"水\"字共4笔：竖、横折钩、撇、捺', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.685', NULL, '2026-08-09 01:14:58.685', NULL);
INSERT INTO `edu_question` VALUES (3110000000000005, 1100000000000001, 2110000000000004, 'single', 1, '\"b、p、m、f\"属于哪类声母？', '[{\"key\": \"A\", \"text\": \"舌尖音\"}, {\"key\": \"B\", \"text\": \"唇音\"}, {\"key\": \"C\", \"text\": \"翘舌音\"}, {\"key\": \"D\", \"text\": \"舌根音\"}]', 'B', 'b/p/m/f是双唇音或唇齿音，统称唇音', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.320', NULL, '2026-08-09 02:27:36.320', NULL);
INSERT INTO `edu_question` VALUES (3110000000000006, 1100000000000001, 2110000000000004, 'single', 1, '拼音\"ang\"属于？', '[{\"key\": \"A\", \"text\": \"单韵母\"}, {\"key\": \"B\", \"text\": \"复韵母\"}, {\"key\": \"C\", \"text\": \"鼻韵母\"}, {\"key\": \"D\", \"text\": \"声母\"}]', 'C', 'ang是后鼻音韵母（鼻韵母）', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.320', NULL, '2026-08-09 02:27:36.320', NULL);
INSERT INTO `edu_question` VALUES (3110000000000007, 1100000000000001, 2110000000000005, 'single', 1, '\"牛\"字的正确拼音声调是？', '[{\"key\": \"A\", \"text\": \"nǐu\"}, {\"key\": \"B\", \"text\": \"niú\"}, {\"key\": \"C\", \"text\": \"niū\"}, {\"key\": \"D\", \"text\": \"niǔ\"}]', 'B', '\"牛\"读niú，第二声（阳平）', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.320', NULL, '2026-08-09 02:27:36.320', NULL);
INSERT INTO `edu_question` VALUES (3110000000000008, 1100000000000001, 2110000000000005, 'single', 1, '\"马\"字读第几声？', '[{\"key\": \"A\", \"text\": \"第一声\"}, {\"key\": \"B\", \"text\": \"第二声\"}, {\"key\": \"C\", \"text\": \"第三声\"}, {\"key\": \"D\", \"text\": \"第四声\"}]', 'C', '\"马\"读mǎ，第三声（上声）', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.320', NULL, '2026-08-09 02:27:36.320', NULL);
INSERT INTO `edu_question` VALUES (3110000000000009, 1100000000000001, 2110000000000006, 'single', 2, '\"日\"字共有几画？', '[{\"key\": \"A\", \"text\": \"3画\"}, {\"key\": \"B\", \"text\": \"4画\"}, {\"key\": \"C\", \"text\": \"5画\"}, {\"key\": \"D\", \"text\": \"6画\"}]', 'B', '\"日\"字共4笔：竖、折、横、横', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.320', NULL, '2026-08-09 02:27:36.320', NULL);
INSERT INTO `edu_question` VALUES (3110000000000010, 1100000000000001, 2110000000000006, 'single', 2, '汉字的基本笔画\"横折钩\"中，最后一笔是？', '[{\"key\": \"A\", \"text\": \"横\"}, {\"key\": \"B\", \"text\": \"折\"}, {\"key\": \"C\", \"text\": \"钩\"}, {\"key\": \"D\", \"text\": \"竖\"}]', 'C', '横折钩由横、折、钩三部分组成，最后一笔是钩', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.320', NULL, '2026-08-09 02:27:36.320', NULL);
INSERT INTO `edu_question` VALUES (3120000000000001, 1100000000000002, 2120000000000004, 'single', 1, '35 + 47 = ？', '[{\"key\": \"A\", \"text\": \"72\"}, {\"key\": \"B\", \"text\": \"82\"}, {\"key\": \"C\", \"text\": \"83\"}, {\"key\": \"D\", \"text\": \"73\"}]', 'B', '5+7=12进1，3+4+1=8，结果是82', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.701', NULL, '2026-08-09 01:14:58.701', NULL);
INSERT INTO `edu_question` VALUES (3120000000000002, 1100000000000002, 2120000000000004, 'single', 2, '100 - 38 = ？', '[{\"key\": \"A\", \"text\": \"72\"}, {\"key\": \"B\", \"text\": \"62\"}, {\"key\": \"C\", \"text\": \"68\"}, {\"key\": \"D\", \"text\": \"78\"}]', 'B', '100-38，从个位借位，0-8不够，退位后10-8=2，十位退后9-3=6，结果62', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.701', NULL, '2026-08-09 01:14:58.701', NULL);
INSERT INTO `edu_question` VALUES (3120000000000003, 1100000000000002, 2120000000000005, 'single', 2, '用竖式计算 23×4，结果是？', '[{\"key\": \"A\", \"text\": \"82\"}, {\"key\": \"B\", \"text\": \"92\"}, {\"key\": \"C\", \"text\": \"93\"}, {\"key\": \"D\", \"text\": \"83\"}]', 'B', '23×4：3×4=12写2进1；2×4=8+1=9；结果92', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.701', NULL, '2026-08-09 01:14:58.701', NULL);
INSERT INTO `edu_question` VALUES (3120000000000004, 1100000000000002, 2120000000000006, 'single', 1, '6×7 = ？', '[{\"key\": \"A\", \"text\": \"42\"}, {\"key\": \"B\", \"text\": \"48\"}, {\"key\": \"C\", \"text\": \"36\"}, {\"key\": \"D\", \"text\": \"54\"}]', 'A', '乘法口诀：六七四十二', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.701', NULL, '2026-08-09 01:14:58.701', NULL);
INSERT INTO `edu_question` VALUES (3120000000000005, 1100000000000002, 2120000000000004, 'single', 2, '48 + 35 = ？', '[{\"key\": \"A\", \"text\": \"73\"}, {\"key\": \"B\", \"text\": \"83\"}, {\"key\": \"C\", \"text\": \"82\"}, {\"key\": \"D\", \"text\": \"74\"}]', 'B', '8+5=13进1，4+3+1=8，结果83', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.333', NULL, '2026-08-09 02:27:36.333', NULL);
INSERT INTO `edu_question` VALUES (3120000000000006, 1100000000000002, 2120000000000004, 'single', 2, '132 - 67 = ？', '[{\"key\": \"A\", \"text\": \"65\"}, {\"key\": \"B\", \"text\": \"75\"}, {\"key\": \"C\", \"text\": \"55\"}, {\"key\": \"D\", \"text\": \"45\"}]', 'A', '132-67：个位2<7借位，12-7=5；十位2借出后1<6借位，11-6=5；百位0；结果65', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.333', NULL, '2026-08-09 02:27:36.333', NULL);
INSERT INTO `edu_question` VALUES (3120000000000007, 1100000000000002, 2120000000000005, 'single', 2, '用竖式计算 45×3，结果是？', '[{\"key\": \"A\", \"text\": \"125\"}, {\"key\": \"B\", \"text\": \"135\"}, {\"key\": \"C\", \"text\": \"145\"}, {\"key\": \"D\", \"text\": \"115\"}]', 'B', '5×3=15写5进1；4×3=12+1=13；结果135', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.333', NULL, '2026-08-09 02:27:36.333', NULL);
INSERT INTO `edu_question` VALUES (3120000000000008, 1100000000000002, 2120000000000005, 'single', 2, '用竖式计算 84÷4，结果是？', '[{\"key\": \"A\", \"text\": \"19\"}, {\"key\": \"B\", \"text\": \"21\"}, {\"key\": \"C\", \"text\": \"22\"}, {\"key\": \"D\", \"text\": \"23\"}]', 'B', '84÷4：8÷4=2，4÷4=1，结果21', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.333', NULL, '2026-08-09 02:27:36.333', NULL);
