INSERT INTO `edu_question` VALUES (3130000000000004, 1100000000000003, 2130000000000006, 'single', 1, '\"红色\"用英语表示是？', '[{\"key\": \"A\", \"text\": \"blue\"}, {\"key\": \"B\", \"text\": \"green\"}, {\"key\": \"C\", \"text\": \"red\"}, {\"key\": \"D\", \"text\": \"yellow\"}]', 'C', 'red=红色，blue=蓝色，green=绿色，yellow=黄色', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.715', NULL, '2026-08-09 01:14:58.715', NULL);
