INSERT INTO `edu_question` VALUES (3130000000000006, 1100000000000003, 2130000000000004, 'single', 1, '26个字母中，大小写形态完全不同的是？', '[{\"key\": \"A\", \"text\": \"O\"}, {\"key\": \"B\", \"text\": \"S\"}, {\"key\": \"C\", \"text\": \"A\"}, {\"key\": \"D\", \"text\": \"G\"}]', 'D', 'G的大写G和小写g外形差异最大', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.347', NULL, '2026-08-09 02:27:36.347', NULL);
INSERT INTO `edu_question` VALUES (3130000000000007, 1100000000000003, 2130000000000005, 'single', 1, '字母\"e\"在单词\"me\"中发什么音？', '[{\"key\": \"A\", \"text\": \"/e/\"}, {\"key\": \"B\", \"text\": \"/ɪ/\"}, {\"key\": \"C\", \"text\": \"/iː/\"}, {\"key\": \"D\", \"text\": \"/ə/\"}]', 'C', 'me中e发长元音/iː/', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.347', NULL, '2026-08-09 02:27:36.347', NULL);
