INSERT INTO `edu_question` VALUES (3140000000000001, 1100000000000004, 2140000000000004, 'single', 2, '植物进行光合作用需要哪种气体？', '[{\"key\": \"A\", \"text\": \"氧气\"}, {\"key\": \"B\", \"text\": \"氮气\"}, {\"key\": \"C\", \"text\": \"二氧化碳\"}, {\"key\": \"D\", \"text\": \"氢气\"}]', 'C', '光合作用吸收CO₂，释放O₂', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.727', NULL, '2026-08-09 01:14:58.727', NULL);
INSERT INTO `edu_question` VALUES (3140000000000002, 1100000000000004, 2140000000000005, 'single', 1, '植物的哪个部分负责吸收水分和无机盐？', '[{\"key\": \"A\", \"text\": \"叶子\"}, {\"key\": \"B\", \"text\": \"根\"}, {\"key\": \"C\", \"text\": \"茎\"}, {\"key\": \"D\", \"text\": \"花\"}]', 'B', '根系负责吸收水分和无机盐', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.727', NULL, '2026-08-09 01:14:58.727', NULL);
INSERT INTO `edu_question` VALUES (3140000000000003, 1100000000000004, 2140000000000006, 'single', 2, '下列哪种动物是哺乳动物？', '[{\"key\": \"A\", \"text\": \"青蛙\"}, {\"key\": \"B\", \"text\": \"鲤鱼\"}, {\"key\": \"C\", \"text\": \"老鹰\"}, {\"key\": \"D\", \"text\": \"鲸鱼\"}]', 'D', '鲸鱼是哺乳动物，用肺呼吸，胎生哺乳', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.727', NULL, '2026-08-09 01:14:58.727', NULL);
INSERT INTO `edu_question` VALUES (3140000000000004, 1100000000000004, 2140000000000004, 'single', 2, '光合作用产生的气体是？', '[{\"key\": \"A\", \"text\": \"二氧化碳\"}, {\"key\": \"B\", \"text\": \"氧气\"}, {\"key\": \"C\", \"text\": \"氮气\"}, {\"key\": \"D\", \"text\": \"水蒸气\"}]', 'B', '光合作用释放氧气，吸收二氧化碳', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.359', NULL, '2026-08-09 02:27:36.359', NULL);
INSERT INTO `edu_question` VALUES (3140000000000005, 1100000000000004, 2140000000000004, 'single', 2, '光合作用主要发生在植物的哪个部位？', '[{\"key\": \"A\", \"text\": \"根\"}, {\"key\": \"B\", \"text\": \"茎\"}, {\"key\": \"C\", \"text\": \"叶\"}, {\"key\": \"D\", \"text\": \"花\"}]', 'C', '叶片中有叶绿体，是光合作用的主要场所', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.359', NULL, '2026-08-09 02:27:36.359', NULL);
INSERT INTO `edu_question` VALUES (3140000000000006, 1100000000000004, 2140000000000005, 'single', 1, '植物的哪个部位负责输送水分和养料？', '[{\"key\": \"A\", \"text\": \"根\"}, {\"key\": \"B\", \"text\": \"茎\"}, {\"key\": \"C\", \"text\": \"叶\"}, {\"key\": \"D\", \"text\": \"花\"}]', 'B', '茎中有导管（运水）和筛管（运有机物）', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.359', NULL, '2026-08-09 02:27:36.359', NULL);
INSERT INTO `edu_question` VALUES (3140000000000007, 1100000000000004, 2140000000000005, 'single', 1, '花的哪个部分发育成果实？', '[{\"key\": \"A\", \"text\": \"花瓣\"}, {\"key\": \"B\", \"text\": \"雄蕊\"}, {\"key\": \"C\", \"text\": \"子房\"}, {\"key\": \"D\", \"text\": \"花托\"}]', 'C', '子房受精后发育成果实', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.359', NULL, '2026-08-09 02:27:36.359', NULL);
INSERT INTO `edu_question` VALUES (3140000000000008, 1100000000000004, 2140000000000006, 'single', 2, '下列哪种动物属于爬行动物？', '[{\"key\": \"A\", \"text\": \"青蛙\"}, {\"key\": \"B\", \"text\": \"蜥蜴\"}, {\"key\": \"C\", \"text\": \"鲤鱼\"}, {\"key\": \"D\", \"text\": \"蝙蝠\"}]', 'B', '蜥蜴是爬行动物；青蛙是两栖动物；鲤鱼是鱼类；蝙蝠是哺乳动物', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.359', NULL, '2026-08-09 02:27:36.359', NULL);
INSERT INTO `edu_question` VALUES (3140000000000009, 1100000000000004, 2140000000000006, 'single', 2, '鸟类区别于其他动物的最主要特征是？', '[{\"key\": \"A\", \"text\": \"能飞翔\"}, {\"key\": \"B\", \"text\": \"有翅膀\"}, {\"key\": \"C\", \"text\": \"体表有羽毛，卵生\"}, {\"key\": \"D\", \"text\": \"恒温动物\"}]', 'C', '鸟类的主要特征是体表被羽毛、卵生、前肢变翅', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.359', NULL, '2026-08-09 02:27:36.359', NULL);
INSERT INTO `edu_question` VALUES (3210000000000001, 1200000000000001, 2210000000000004, 'single', 3, '下列\"学而时习之\"中\"学\"与\"习\"的关系，哪项解释正确？', '[{\"key\": \"A\", \"text\": \"学习新知识，反复温习\"}, {\"key\": \"B\", \"text\": \"向别人学习\"}, {\"key\": \"C\", \"text\": \"学习礼仪\"}, {\"key\": \"D\", \"text\": \"读书写字\"}]', 'A', '\"学\"指接受知识，\"习\"指实践复习，合在一起是学习并经常温习', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.739', NULL, '2026-08-09 01:14:58.739', NULL);
INSERT INTO `edu_question` VALUES (3210000000000002, 1200000000000001, 2210000000000004, 'single', 3, '\"蒙乃始就学\"中\"就\"的意思是？', '[{\"key\": \"A\", \"text\": \"接近\"}, {\"key\": \"B\", \"text\": \"就是\"}, {\"key\": \"C\", \"text\": \"前往\"}, {\"key\": \"D\", \"text\": \"开始\"}]', 'C', '\"就\"在文言文中常有\"前往、去\"的意思', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.739', NULL, '2026-08-09 01:14:58.739', NULL);
INSERT INTO `edu_question` VALUES (3210000000000003, 1200000000000001, 2210000000000005, 'single', 3, '\"孤岂欲卿治经为博士邪\"中\"邪\"的用法是？', '[{\"key\": \"A\", \"text\": \"语气助词，表疑问\"}, {\"key\": \"B\", \"text\": \"邪恶的\"}, {\"key\": \"C\", \"text\": \"方向词\"}, {\"key\": \"D\", \"text\": \"连词\"}]', 'A', '\"邪\"通\"耶\"，文言疑问语气词', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.739', NULL, '2026-08-09 01:14:58.739', NULL);
INSERT INTO `edu_question` VALUES (3210000000000004, 1200000000000001, 2210000000000006, 'single', 3, '\"大道之行也，天下为公\"中\"为\"是判断句的标志，这句属于？', '[{\"key\": \"A\", \"text\": \"省略句\"}, {\"key\": \"B\", \"text\": \"判断句\"}, {\"key\": \"C\", \"text\": \"被动句\"}, {\"key\": \"D\", \"text\": \"倒装句\"}]', 'B', '\"天下为公\"是典型判断句，\"为\"表示\"是\"', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.739', NULL, '2026-08-09 01:14:58.739', NULL);
INSERT INTO `edu_question` VALUES (3210000000000005, 1200000000000001, 2210000000000004, 'single', 3, '\"学而时习之，不亦说乎\"中\"说\"通哪个字？', '[{\"key\": \"A\", \"text\": \"话\"}, {\"key\": \"B\", \"text\": \"悦\"}, {\"key\": \"C\", \"text\": \"税\"}, {\"key\": \"D\", \"text\": \"脱\"}]', 'B', '\"说\"通\"悦\"，高兴的意思', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.372', NULL, '2026-08-09 02:27:36.372', NULL);
INSERT INTO `edu_question` VALUES (3210000000000006, 1200000000000001, 2210000000000004, 'single', 3, '\"甚矣，汝之不惠\"中\"惠\"通哪个字？', '[{\"key\": \"A\", \"text\": \"会\"}, {\"key\": \"B\", \"text\": \"慧\"}, {\"key\": \"C\", \"text\": \"贿\"}, {\"key\": \"D\", \"text\": \"汇\"}]', 'B', '\"惠\"通\"慧\"，聪明的意思', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.372', NULL, '2026-08-09 02:27:36.372', NULL);
INSERT INTO `edu_question` VALUES (3210000000000007, 1200000000000001, 2210000000000005, 'single', 3, '\"吾妻之美我者\"中\"美\"的词类活用是？', '[{\"key\": \"A\", \"text\": \"名词作动词\"}, {\"key\": \"B\", \"text\": \"形容词的意动用法\"}, {\"key\": \"C\", \"text\": \"动词作名词\"}, {\"key\": \"D\", \"text\": \"形容词作副词\"}]', 'B', '\"美我\"是意动用法，\"认为我美\"', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.372', NULL, '2026-08-09 02:27:36.372', NULL);
INSERT INTO `edu_question` VALUES (3210000000000008, 1200000000000001, 2210000000000005, 'single', 3, '\"域民不以封疆之界\"中\"域\"的词类活用是？', '[{\"key\": \"A\", \"text\": \"形容词作动词\"}, {\"key\": \"B\", \"text\": \"名词作动词\"}, {\"key\": \"C\", \"text\": \"名词作状语\"}, {\"key\": \"D\", \"text\": \"动词作名词\"}]', 'B', '\"域\"原是名词（疆域），此处作动词用，意为\"限制\"', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.372', NULL, '2026-08-09 02:27:36.372', NULL);
INSERT INTO `edu_question` VALUES (3210000000000009, 1200000000000001, 2210000000000006, 'single', 3, '\"陈胜者，阳城人也\"是什么句式？', '[{\"key\": \"A\", \"text\": \"被动句\"}, {\"key\": \"B\", \"text\": \"省略句\"}, {\"key\": \"C\", \"text\": \"判断句\"}, {\"key\": \"D\", \"text\": \"疑问句\"}]', 'C', '\"……者，……也\"是文言判断句的典型结构', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.372', NULL, '2026-08-09 02:27:36.372', NULL);
INSERT INTO `edu_question` VALUES (3210000000000010, 1200000000000001, 2210000000000006, 'single', 3, '\"见渔人，乃大惊\"中省略的主语是？', '[{\"key\": \"A\", \"text\": \"桃花源中人\"}, {\"key\": \"B\", \"text\": \"渔人\"}, {\"key\": \"C\", \"text\": \"村人\"}, {\"key\": \"D\", \"text\": \"无法判断\"}]', 'A', '根据上下文，省略的主语是桃花源中人', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.372', NULL, '2026-08-09 02:27:36.372', NULL);
INSERT INTO `edu_question` VALUES (3220000000000001, 1200000000000002, 2220000000000004, 'single', 2, '解方程 3x + 6 = 15，移项后得到？', '[{\"key\": \"A\", \"text\": \"3x = 21\"}, {\"key\": \"B\", \"text\": \"3x = 9\"}, {\"key\": \"C\", \"text\": \"3x = -9\"}, {\"key\": \"D\", \"text\": \"x = 9\"}]', 'B', '将常数项6移到右边变符号：3x = 15 - 6 = 9', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.751', NULL, '2026-08-09 01:14:58.751', NULL);
INSERT INTO `edu_question` VALUES (3220000000000002, 1200000000000002, 2220000000000005, 'single', 2, '解方程 2x - 4 = 8，x的值是？', '[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"6\"}, {\"key\": \"C\", \"text\": \"4\"}, {\"key\": \"D\", \"text\": \"8\"}]', 'B', '2x = 8 + 4 = 12，x = 6', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.751', NULL, '2026-08-09 01:14:58.751', NULL);
INSERT INTO `edu_question` VALUES (3220000000000003, 1200000000000002, 2220000000000006, 'single', 3, '用代入法解方程组：y = x + 1 且 x + y = 5，x的值是？', '[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"3\"}, {\"key\": \"C\", \"text\": \"4\"}, {\"key\": \"D\", \"text\": \"1\"}]', 'A', '代入：x + (x+1) = 5 → 2x+1=5 → x=2', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.751', NULL, '2026-08-09 01:14:58.751', NULL);
INSERT INTO `edu_question` VALUES (3220000000000004, 1200000000000002, 2220000000000006, 'single', 3, '解方程组：{2x+y=7, x-y=2}，y的值是？', '[{\"key\": \"A\", \"text\": \"1\"}, {\"key\": \"B\", \"text\": \"2\"}, {\"key\": \"C\", \"text\": \"3\"}, {\"key\": \"D\", \"text\": \"4\"}]', 'C', '两式相加：3x=9，x=3，代入得y=3-2=1，故y=1... 等等：y=7-2×3=1。选A', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.751', NULL, '2026-08-09 01:14:58.751', NULL);
INSERT INTO `edu_question` VALUES (3220000000000005, 1200000000000002, 2220000000000004, 'single', 2, '解方程 5x - 10 = 0，移项后得？', '[{\"key\": \"A\", \"text\": \"5x = 10\"}, {\"key\": \"B\", \"text\": \"5x = -10\"}, {\"key\": \"C\", \"text\": \"-5x = 10\"}, {\"key\": \"D\", \"text\": \"x = 10\"}]', 'A', '将-10移到右边变号：5x = 10', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.385', NULL, '2026-08-09 02:27:36.385', NULL);
INSERT INTO `edu_question` VALUES (3220000000000006, 1200000000000002, 2220000000000004, 'single', 2, '移项时，下列说法正确的是？', '[{\"key\": \"A\", \"text\": \"移项不变号\"}, {\"key\": \"B\", \"text\": \"移项要变号\"}, {\"key\": \"C\", \"text\": \"只有正数才能移项\"}, {\"key\": \"D\", \"text\": \"只有负数才能移项\"}]', 'B', '移项是等式两边同时加减同一个数，移到另一边符号改变', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.385', NULL, '2026-08-09 02:27:36.385', NULL);
INSERT INTO `edu_question` VALUES (3220000000000007, 1200000000000002, 2220000000000005, 'single', 2, '解方程 4x = -20，x的值是？', '[{\"key\": \"A\", \"text\": \"5\"}, {\"key\": \"B\", \"text\": \"-5\"}, {\"key\": \"C\", \"text\": \"80\"}, {\"key\": \"D\", \"text\": \"-80\"}]', 'B', 'x = -20÷4 = -5', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.385', NULL, '2026-08-09 02:27:36.385', NULL);
INSERT INTO `edu_question` VALUES (3220000000000008, 1200000000000002, 2220000000000005, 'single', 2, '解方程 -3x + 9 = 0，x的值是？', '[{\"key\": \"A\", \"text\": \"3\"}, {\"key\": \"B\", \"text\": \"-3\"}, {\"key\": \"C\", \"text\": \"27\"}, {\"key\": \"D\", \"text\": \"-27\"}]', 'A', '-3x = -9，x = 3', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.385', NULL, '2026-08-09 02:27:36.385', NULL);
INSERT INTO `edu_question` VALUES (3220000000000009, 1200000000000002, 2220000000000006, 'single', 3, '解方程组：{y = 2x, x + y = 9}，x的值是？', '[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"3\"}, {\"key\": \"C\", \"text\": \"6\"}, {\"key\": \"D\", \"text\": \"9\"}]', 'B', '代入：x + 2x = 9，3x = 9，x = 3', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.385', NULL, '2026-08-09 02:27:36.385', NULL);
INSERT INTO `edu_question` VALUES (3220000000000010, 1200000000000002, 2220000000000006, 'single', 3, '解方程组：{2x + 3y = 12, x = y + 1}，y的值是？', '[{\"key\": \"A\", \"text\": \"1\"}, {\"key\": \"B\", \"text\": \"2\"}, {\"key\": \"C\", \"text\": \"3\"}, {\"key\": \"D\", \"text\": \"4\"}]', 'B', '代入：2(y+1)+3y=12，5y+2=12，y=2', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.385', NULL, '2026-08-09 02:27:36.385', NULL);
INSERT INTO `edu_question` VALUES (3230000000000001, 1200000000000003, 2230000000000004, 'single', 2, 'She ___ to school every day. (一般现在时，主语She)', '[{\"key\": \"A\", \"text\": \"go\"}, {\"key\": \"B\", \"text\": \"goes\"}, {\"key\": \"C\", \"text\": \"went\"}, {\"key\": \"D\", \"text\": \"going\"}]', 'B', '第三人称单数一般现在时，动词加s/es，go→goes', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.764', NULL, '2026-08-09 01:14:58.764', NULL);
INSERT INTO `edu_question` VALUES (3230000000000002, 1200000000000003, 2230000000000005, 'single', 2, 'Do they like music? 正确否定回答是？', '[{\"key\": \"A\", \"text\": \"No, they don\'t.\"}, {\"key\": \"B\", \"text\": \"No, they doesn\'t.\"}, {\"key\": \"C\", \"text\": \"No, they didn\'t.\"}, {\"key\": \"D\", \"text\": \"No, they aren\'t.\"}]', 'A', 'they是复数，否定助动词用don\'t', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.764', NULL, '2026-08-09 01:14:58.764', NULL);
INSERT INTO `edu_question` VALUES (3230000000000003, 1200000000000003, 2230000000000006, 'single', 2, '\"play\"的过去式是？', '[{\"key\": \"A\", \"text\": \"plaied\"}, {\"key\": \"B\", \"text\": \"played\"}, {\"key\": \"C\", \"text\": \"plaied\"}, {\"key\": \"D\", \"text\": \"plied\"}]', 'B', '辅音+y结尾去y加ied不适用（play以元音+y结尾），直接加d→played', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.764', NULL, '2026-08-09 01:14:58.764', NULL);
INSERT INTO `edu_question` VALUES (3230000000000004, 1200000000000003, 2230000000000006, 'single', 2, '\"stop\"的过去式是？', '[{\"key\": \"A\", \"text\": \"stoped\"}, {\"key\": \"B\", \"text\": \"stoping\"}, {\"key\": \"C\", \"text\": \"stopped\"}, {\"key\": \"D\", \"text\": \"stopp\"}]', 'C', '短元音+单辅音结尾，双写辅音再加ed：stopped', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.764', NULL, '2026-08-09 01:14:58.764', NULL);
INSERT INTO `edu_question` VALUES (3230000000000005, 1200000000000003, 2230000000000004, 'single', 2, 'He ___ a book every week. (一般现在时)', '[{\"key\": \"A\", \"text\": \"read\"}, {\"key\": \"B\", \"text\": \"reads\"}, {\"key\": \"C\", \"text\": \"reading\"}, {\"key\": \"D\", \"text\": \"readed\"}]', 'B', '第三人称单数一般现在时，read→reads', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.399', NULL, '2026-08-09 02:27:36.399', NULL);
INSERT INTO `edu_question` VALUES (3230000000000006, 1200000000000003, 2230000000000004, 'single', 2, 'Tom ___ English very well.', '[{\"key\": \"A\", \"text\": \"speak\"}, {\"key\": \"B\", \"text\": \"speaks\"}, {\"key\": \"C\", \"text\": \"spoke\"}, {\"key\": \"D\", \"text\": \"speaking\"}]', 'B', 'Tom是第三人称单数，一般现在时speak加s→speaks', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.399', NULL, '2026-08-09 02:27:36.399', NULL);
INSERT INTO `edu_question` VALUES (3230000000000007, 1200000000000003, 2230000000000005, 'single', 2, 'He likes coffee. 变否定句：', '[{\"key\": \"A\", \"text\": \"He don\'t likes coffee.\"}, {\"key\": \"B\", \"text\": \"He doesn\'t like coffee.\"}, {\"key\": \"C\", \"text\": \"He doesn\'t likes coffee.\"}, {\"key\": \"D\", \"text\": \"He not like coffee.\"}]', 'B', '第三人称单数否定用doesn\'t，后接动词原形like', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.399', NULL, '2026-08-09 02:27:36.399', NULL);
INSERT INTO `edu_question` VALUES (3230000000000008, 1200000000000003, 2230000000000005, 'single', 2, 'They study math. 变一般疑问句：', '[{\"key\": \"A\", \"text\": \"Does they study math?\"}, {\"key\": \"B\", \"text\": \"Do they study math?\"}, {\"key\": \"C\", \"text\": \"Did they study math?\"}, {\"key\": \"D\", \"text\": \"Are they study math?\"}]', 'B', 'they是复数，一般现在时疑问句用Do', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.399', NULL, '2026-08-09 02:27:36.399', NULL);
INSERT INTO `edu_question` VALUES (3230000000000009, 1200000000000003, 2230000000000006, 'single', 2, '\"watch\"的过去式是？', '[{\"key\": \"A\", \"text\": \"watchd\"}, {\"key\": \"B\", \"text\": \"watched\"}, {\"key\": \"C\", \"text\": \"wached\"}, {\"key\": \"D\", \"text\": \"wathed\"}]', 'B', '规则动词一般加ed，watch→watched', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.399', NULL, '2026-08-09 02:27:36.399', NULL);
INSERT INTO `edu_question` VALUES (3230000000000010, 1200000000000003, 2230000000000006, 'single', 2, '\"study\"的过去式是？', '[{\"key\": \"A\", \"text\": \"studyed\"}, {\"key\": \"B\", \"text\": \"studied\"}, {\"key\": \"C\", \"text\": \"studid\"}, {\"key\": \"D\", \"text\": \"stodied\"}]', 'B', '辅音+y结尾，去y加ied：study→studied', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.399', NULL, '2026-08-09 02:27:36.399', NULL);
INSERT INTO `edu_question` VALUES (3240000000000001, 1200000000000004, 2240000000000004, 'single', 2, '力的三要素是？', '[{\"key\": \"A\", \"text\": \"大小、方向、作用点\"}, {\"key\": \"B\", \"text\": \"大小、速度、位置\"}, {\"key\": \"C\", \"text\": \"质量、加速度、时间\"}, {\"key\": \"D\", \"text\": \"方向、速度、形状\"}]', 'A', '力的三要素：大小、方向、作用点', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.777', NULL, '2026-08-09 01:14:58.777', NULL);
INSERT INTO `edu_question` VALUES (3240000000000002, 1200000000000004, 2240000000000005, 'single', 3, '两个力大小分别为3N和4N，方向相同，合力大小是？', '[{\"key\": \"A\", \"text\": \"1N\"}, {\"key\": \"B\", \"text\": \"5N\"}, {\"key\": \"C\", \"text\": \"7N\"}, {\"key\": \"D\", \"text\": \"25N\"}]', 'C', '同向合力为代数和：3+4=7N', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.777', NULL, '2026-08-09 01:14:58.777', NULL);
INSERT INTO `edu_question` VALUES (3240000000000003, 1200000000000004, 2240000000000006, 'single', 3, '牛顿第一定律的内容描述的是？', '[{\"key\": \"A\", \"text\": \"物体受到力就运动\"}, {\"key\": \"B\", \"text\": \"不受力时物体保持静止或匀速直线运动\"}, {\"key\": \"C\", \"text\": \"力越大加速度越大\"}, {\"key\": \"D\", \"text\": \"作用力等于反作用力\"}]', 'B', '牛一：不受外力时，物体保持匀速直线运动或静止状态（惯性定律）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.777', NULL, '2026-08-09 01:14:58.777', NULL);
INSERT INTO `edu_question` VALUES (3240000000000004, 1200000000000004, 2240000000000006, 'single', 2, '下列哪个例子体现了惯性？', '[{\"key\": \"A\", \"text\": \"苹果落地\"}, {\"key\": \"B\", \"text\": \"汽车刹车后乘客向前倾\"}, {\"key\": \"C\", \"text\": \"马拉车车前进\"}, {\"key\": \"D\", \"text\": \"风筝升空\"}]', 'B', '刹车后人继续向前运动是惯性，身体还保持原来的运动状态', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.777', NULL, '2026-08-09 01:14:58.777', NULL);
INSERT INTO `edu_question` VALUES (3240000000000005, 1200000000000004, 2240000000000004, 'single', 2, '用箭头表示力时，箭头方向表示力的？', '[{\"key\": \"A\", \"text\": \"大小\"}, {\"key\": \"B\", \"text\": \"作用点\"}, {\"key\": \"C\", \"text\": \"方向\"}, {\"key\": \"D\", \"text\": \"单位\"}]', 'C', '力的示意图中箭头方向表示力的方向', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.414', NULL, '2026-08-09 02:27:36.414', NULL);
INSERT INTO `edu_question` VALUES (3240000000000006, 1200000000000004, 2240000000000004, 'single', 2, '下列关于力的说法，正确的是？', '[{\"key\": \"A\", \"text\": \"力可以离开物体单独存在\"}, {\"key\": \"B\", \"text\": \"只有运动的物体才受力\"}, {\"key\": \"C\", \"text\": \"力是物体对物体的作用\"}, {\"key\": \"D\", \"text\": \"力的作用是单向的\"}]', 'C', '力是物体对物体的作用，必须有施力物体和受力物体', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.414', NULL, '2026-08-09 02:27:36.414', NULL);
INSERT INTO `edu_question` VALUES (3240000000000007, 1200000000000004, 2240000000000005, 'single', 3, '两个力大小均为5N，方向相反，合力大小是？', '[{\"key\": \"A\", \"text\": \"0N\"}, {\"key\": \"B\", \"text\": \"5N\"}, {\"key\": \"C\", \"text\": \"10N\"}, {\"key\": \"D\", \"text\": \"25N\"}]', 'A', '方向相反的合力等于差：5-5=0N', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.414', NULL, '2026-08-09 02:27:36.414', NULL);
INSERT INTO `edu_question` VALUES (3240000000000008, 1200000000000004, 2240000000000005, 'single', 3, '合力与分力的关系，下列说法正确的是？', '[{\"key\": \"A\", \"text\": \"合力一定大于每个分力\"}, {\"key\": \"B\", \"text\": \"合力可以小于某个分力\"}, {\"key\": \"C\", \"text\": \"合力方向与最大分力相同\"}, {\"key\": \"D\", \"text\": \"两个分力之和等于合力大小\"}]', 'B', '当两个分力方向相反时，合力可以小于某个分力', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.414', NULL, '2026-08-09 02:27:36.414', NULL);
INSERT INTO `edu_question` VALUES (3240000000000009, 1200000000000004, 2240000000000006, 'single', 2, '质量越大的物体，惯性？', '[{\"key\": \"A\", \"text\": \"越小\"}, {\"key\": \"B\", \"text\": \"越大\"}, {\"key\": \"C\", \"text\": \"不变\"}, {\"key\": \"D\", \"text\": \"与质量无关\"}]', 'B', '惯性大小只与质量有关，质量越大惯性越大', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.414', NULL, '2026-08-09 02:27:36.414', NULL);
INSERT INTO `edu_question` VALUES (3240000000000010, 1200000000000004, 2240000000000006, 'single', 3, '在太空失重环境下，宇航员的惯性？', '[{\"key\": \"A\", \"text\": \"消失\"}, {\"key\": \"B\", \"text\": \"减小\"}, {\"key\": \"C\", \"text\": \"不变\"}, {\"key\": \"D\", \"text\": \"增大\"}]', 'C', '惯性是物体的固有属性，与所处环境无关，不变', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.414', NULL, '2026-08-09 02:27:36.414', NULL);
INSERT INTO `edu_question` VALUES (3250000000000001, 1200000000000005, 2250000000000004, 'single', 3, '原子核外电子的排布遵循？', '[{\"key\": \"A\", \"text\": \"能量越低的轨道电子数越少\"}, {\"key\": \"B\", \"text\": \"第一层最多2个电子，第二层最多8个\"}, {\"key\": \"C\", \"text\": \"所有层最多8个\"}, {\"key\": \"D\", \"text\": \"电子随机排列\"}]', 'B', '核外电子排布：第一层≤2，第二层≤8，以此类推', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.791', NULL, '2026-08-09 01:14:58.791', NULL);
INSERT INTO `edu_question` VALUES (3250000000000002, 1200000000000005, 2250000000000005, 'single', 3, '元素H₂O中氢和氧的化合价分别是？', '[{\"key\": \"A\", \"text\": \"+1和-2\"}, {\"key\": \"B\", \"text\": \"-1和+2\"}, {\"key\": \"C\", \"text\": \"+2和-1\"}, {\"key\": \"D\", \"text\": \"+1和+2\"}]', 'A', '水中H为+1价，O为-2价，化合物各元素化合价代数和为0', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.791', NULL, '2026-08-09 01:14:58.791', NULL);
INSERT INTO `edu_question` VALUES (3250000000000003, 1200000000000005, 2250000000000006, 'single', 2, '化学式 CO₂ 读作？', '[{\"key\": \"A\", \"text\": \"一氧化碳\"}, {\"key\": \"B\", \"text\": \"二氧化一碳\"}, {\"key\": \"C\", \"text\": \"二氧化碳\"}, {\"key\": \"D\", \"text\": \"碳二氧\"}]', 'C', 'CO₂读作：二氧化碳（氧在前，碳在后，加\"化\"连接，氧有2个）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.791', NULL, '2026-08-09 01:14:58.791', NULL);
INSERT INTO `edu_question` VALUES (3250000000000004, 1200000000000005, 2250000000000006, 'single', 2, 'NaCl 是哪两种元素组成的？', '[{\"key\": \"A\", \"text\": \"氮和氯\"}, {\"key\": \"B\", \"text\": \"钠和钙\"}, {\"key\": \"C\", \"text\": \"钠和氯\"}, {\"key\": \"D\", \"text\": \"钙和氯\"}]', 'C', 'Na=钠，Cl=氯，NaCl=氯化钠（食盐）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.791', NULL, '2026-08-09 01:14:58.791', NULL);
INSERT INTO `edu_question` VALUES (3250000000000005, 1200000000000005, 2250000000000004, 'single', 3, '碳原子的核外电子数是？', '[{\"key\": \"A\", \"text\": \"4\"}, {\"key\": \"B\", \"text\": \"6\"}, {\"key\": \"C\", \"text\": \"8\"}, {\"key\": \"D\", \"text\": \"12\"}]', 'B', '碳的原子序数为6，核外电子数等于质子数=6', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.427', NULL, '2026-08-09 02:27:36.427', NULL);
INSERT INTO `edu_question` VALUES (3250000000000006, 1200000000000005, 2250000000000004, 'single', 3, '原子中，质子数与电子数的关系是？', '[{\"key\": \"A\", \"text\": \"质子数>电子数\"}, {\"key\": \"B\", \"text\": \"质子数=电子数\"}, {\"key\": \"C\", \"text\": \"质子数<电子数\"}, {\"key\": \"D\", \"text\": \"没有规律\"}]', 'B', '中性原子中，质子数=核外电子数', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.427', NULL, '2026-08-09 02:27:36.427', NULL);
INSERT INTO `edu_question` VALUES (3250000000000007, 1200000000000005, 2250000000000005, 'single', 3, 'NaCl中Na和Cl之间形成的化学键是？', '[{\"key\": \"A\", \"text\": \"共价键\"}, {\"key\": \"B\", \"text\": \"离子键\"}, {\"key\": \"C\", \"text\": \"金属键\"}, {\"key\": \"D\", \"text\": \"氢键\"}]', 'B', 'NaCl中Na失去电子变Na⁺，Cl得到电子变Cl⁻，形成离子键', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.427', NULL, '2026-08-09 02:27:36.427', NULL);
INSERT INTO `edu_question` VALUES (3250000000000008, 1200000000000005, 2250000000000005, 'single', 3, 'H₂O中O和H之间形成的化学键是？', '[{\"key\": \"A\", \"text\": \"离子键\"}, {\"key\": \"B\", \"text\": \"金属键\"}, {\"key\": \"C\", \"text\": \"共价键\"}, {\"key\": \"D\", \"text\": \"氢键\"}]', 'C', 'H₂O中非金属元素之间共用电子对，形成共价键', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.427', NULL, '2026-08-09 02:27:36.427', NULL);
INSERT INTO `edu_question` VALUES (3250000000000009, 1200000000000005, 2250000000000006, 'single', 2, 'Fe₂O₃ 读作？', '[{\"key\": \"A\", \"text\": \"二氧化铁\"}, {\"key\": \"B\", \"text\": \"三氧化二铁\"}, {\"key\": \"C\", \"text\": \"氧化铁\"}, {\"key\": \"D\", \"text\": \"铁三氧\"}]', 'B', 'Fe₂O₃读作三氧化二铁（氧在前，铁在后，数字说明个数）', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.427', NULL, '2026-08-09 02:27:36.427', NULL);
INSERT INTO `edu_question` VALUES (3250000000000010, 1200000000000005, 2250000000000006, 'single', 2, 'H₂SO₄ 是什么物质？', '[{\"key\": \"A\", \"text\": \"盐酸\"}, {\"key\": \"B\", \"text\": \"硝酸\"}, {\"key\": \"C\", \"text\": \"硫酸\"}, {\"key\": \"D\", \"text\": \"碳酸\"}]', 'C', 'H₂SO₄是硫酸，S=硫，含2个氢4个氧1个硫', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.427', NULL, '2026-08-09 02:27:36.427', NULL);
INSERT INTO `edu_question` VALUES (3260000000000001, 1200000000000006, 2260000000000004, 'single', 2, '动物细胞有而植物细胞没有的结构是？', '[{\"key\": \"A\", \"text\": \"细胞膜\"}, {\"key\": \"B\", \"text\": \"细胞壁\"}, {\"key\": \"C\", \"text\": \"细胞质\"}, {\"key\": \"D\", \"text\": \"线粒体\"}]', 'B', '植物细胞有细胞壁，动物细胞没有细胞壁', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.805', NULL, '2026-08-09 01:14:58.805', NULL);
INSERT INTO `edu_question` VALUES (3260000000000002, 1200000000000006, 2260000000000005, 'single', 3, '细胞核的主要功能是？', '[{\"key\": \"A\", \"text\": \"提供能量\"}, {\"key\": \"B\", \"text\": \"遗传信息的载体和控制中心\"}, {\"key\": \"C\", \"text\": \"合成蛋白质\"}, {\"key\": \"D\", \"text\": \"进行光合作用\"}]', 'B', '细胞核是遗传信息（DNA）的存储和表达控制中心', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.805', NULL, '2026-08-09 01:14:58.805', NULL);
INSERT INTO `edu_question` VALUES (3260000000000003, 1200000000000006, 2260000000000006, 'single', 3, '有丝分裂中染色体数目加倍发生在哪个阶段？', '[{\"key\": \"A\", \"text\": \"间期\"}, {\"key\": \"B\", \"text\": \"前期\"}, {\"key\": \"C\", \"text\": \"中期\"}, {\"key\": \"D\", \"text\": \"后期\"}]', 'D', '后期着丝点分裂，染色体数目加倍', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.805', NULL, '2026-08-09 01:14:58.805', NULL);
INSERT INTO `edu_question` VALUES (3260000000000004, 1200000000000006, 2260000000000006, 'single', 3, '有丝分裂与减数分裂的区别是？', '[{\"key\": \"A\", \"text\": \"有丝分裂产生4个子细胞\"}, {\"key\": \"B\", \"text\": \"减数分裂只发生在性细胞形成时\"}, {\"key\": \"C\", \"text\": \"有丝分裂子细胞染色体减半\"}, {\"key\": \"D\", \"text\": \"减数分裂产生体细胞\"}]', 'B', '减数分裂专门用于形成配子（精子/卵子），染色体减半', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.805', NULL, '2026-08-09 01:14:58.805', NULL);
INSERT INTO `edu_question` VALUES (3260000000000005, 1200000000000006, 2260000000000004, 'single', 2, '细胞膜的主要功能是？', '[{\"key\": \"A\", \"text\": \"提供细胞支撑\"}, {\"key\": \"B\", \"text\": \"控制物质进出细胞\"}, {\"key\": \"C\", \"text\": \"进行光合作用\"}, {\"key\": \"D\", \"text\": \"储存遗传信息\"}]', 'B', '细胞膜是选择透过性膜，控制细胞与外界的物质交换', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.442', NULL, '2026-08-09 02:27:36.442', NULL);
INSERT INTO `edu_question` VALUES (3260000000000006, 1200000000000006, 2260000000000004, 'single', 2, '植物细胞特有的结构包括？', '[{\"key\": \"A\", \"text\": \"线粒体、核糖体\"}, {\"key\": \"B\", \"text\": \"细胞壁、叶绿体、液泡\"}, {\"key\": \"C\", \"text\": \"细胞核、细胞质\"}, {\"key\": \"D\", \"text\": \"内质网、高尔基体\"}]', 'B', '植物细胞特有：细胞壁、叶绿体（绿色植物）、液泡', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.442', NULL, '2026-08-09 02:27:36.442', NULL);
INSERT INTO `edu_question` VALUES (3260000000000007, 1200000000000006, 2260000000000005, 'single', 3, '细胞核中含有遗传物质的结构是？', '[{\"key\": \"A\", \"text\": \"核膜\"}, {\"key\": \"B\", \"text\": \"核仁\"}, {\"key\": \"C\", \"text\": \"染色质\"}, {\"key\": \"D\", \"text\": \"核孔\"}]', 'C', '染色质（分裂时变为染色体）上含有DNA，即遗传物质', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.442', NULL, '2026-08-09 02:27:36.442', NULL);
INSERT INTO `edu_question` VALUES (3260000000000008, 1200000000000006, 2260000000000005, 'single', 3, '去除细胞核后，细胞会？', '[{\"key\": \"A\", \"text\": \"正常存活\"}, {\"key\": \"B\", \"text\": \"分裂加快\"}, {\"key\": \"C\", \"text\": \"很快死亡\"}, {\"key\": \"D\", \"text\": \"体积增大\"}]', 'C', '细胞核是细胞生命活动的控制中心，去核后细胞很快死亡', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.442', NULL, '2026-08-09 02:27:36.442', NULL);
INSERT INTO `edu_question` VALUES (3260000000000009, 1200000000000006, 2260000000000006, 'single', 3, '有丝分裂中期，染色体的特点是？', '[{\"key\": \"A\", \"text\": \"染色体开始复制\"}, {\"key\": \"B\", \"text\": \"染色体排列在赤道板上\"}, {\"key\": \"C\", \"text\": \"着丝点分裂\"}, {\"key\": \"D\", \"text\": \"核膜消失\"}]', 'B', '分裂中期染色体排列整齐在赤道板，便于观察和计数', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.442', NULL, '2026-08-09 02:27:36.442', NULL);
INSERT INTO `edu_question` VALUES (3260000000000010, 1200000000000006, 2260000000000006, 'single', 3, '一个细胞经有丝分裂后产生几个子细胞？', '[{\"key\": \"A\", \"text\": \"2个\"}, {\"key\": \"B\", \"text\": \"4个\"}, {\"key\": \"C\", \"text\": \"8个\"}, {\"key\": \"D\", \"text\": \"1个\"}]', 'A', '有丝分裂产生2个遗传物质相同的子细胞', NULL, NULL, 0, NULL, '2026-08-09 02:27:36.442', NULL, '2026-08-09 02:27:36.442', NULL);
INSERT INTO `edu_question` VALUES (3310000000000001, 1300000000000001, 2310000000000004, 'single', 3, '\"月落乌啼霜满天\"中\"月\"这一意象的传统含义是？', '[{\"key\": \"A\", \"text\": \"热情奔放\"}, {\"key\": \"B\", \"text\": \"思乡怀人\"}, {\"key\": \"C\", \"text\": \"富贵荣华\"}, {\"key\": \"D\", \"text\": \"春意盎然\"}]', 'B', '月在古诗中常象征思念、乡愁', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.818', NULL, '2026-08-09 01:14:58.818', NULL);
INSERT INTO `edu_question` VALUES (3310000000000002, 1300000000000001, 2310000000000005, 'single', 4, '\"烽火连三月，家书抵万金\"使用了什么表现手法？', '[{\"key\": \"A\", \"text\": \"比喻\"}, {\"key\": \"B\", \"text\": \"夸张\"}, {\"key\": \"C\", \"text\": \"对偶+夸张\"}, {\"key\": \"D\", \"text\": \"排比\"}]', 'C', '对偶句式，\"抵万金\"是夸张手法强调家书的珍贵', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.818', NULL, '2026-08-09 01:14:58.818', NULL);
INSERT INTO `edu_question` VALUES (3310000000000003, 1300000000000001, 2310000000000006, 'single', 4, '律诗的基本格律要求是？', '[{\"key\": \"A\", \"text\": \"四句，偶数句押韵\"}, {\"key\": \"B\", \"text\": \"八句，颔联颈联对仗\"}, {\"key\": \"C\", \"text\": \"六句，首尾押韵\"}, {\"key\": \"D\", \"text\": \"十句，全部对仗\"}]', 'B', '律诗八句，颔联（3-4句）和颈联（5-6句）须对仗', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.818', NULL, '2026-08-09 01:14:58.818', NULL);
INSERT INTO `edu_question` VALUES (3310000000000004, 1300000000000001, 2310000000000004, 'single', 3, '\"松\"在古诗中常象征？', '[{\"key\": \"A\", \"text\": \"柔弱\"}, {\"key\": \"B\", \"text\": \"坚贞、高洁\"}, {\"key\": \"C\", \"text\": \"离别\"}, {\"key\": \"D\", \"text\": \"丰收\"}]', 'B', '松树四季常青、挺拔，常象征坚贞不屈、高洁的品格', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.056', NULL, '2026-08-09 02:30:25.056', NULL);
INSERT INTO `edu_question` VALUES (3310000000000005, 1300000000000001, 2310000000000004, 'single', 3, '\"菊\"在古诗中常代表？', '[{\"key\": \"A\", \"text\": \"富贵\"}, {\"key\": \"B\", \"text\": \"爱情\"}, {\"key\": \"C\", \"text\": \"隐逸、高洁\"}, {\"key\": \"D\", \"text\": \"战争\"}]', 'C', '菊花耐霜，常象征隐逸脱俗、高洁的情操', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.056', NULL, '2026-08-09 02:30:25.056', NULL);
INSERT INTO `edu_question` VALUES (3310000000000006, 1300000000000001, 2310000000000005, 'single', 4, '\"春蚕到死丝方尽，蜡炬成灰泪始干\"使用了什么修辞？', '[{\"key\": \"A\", \"text\": \"排比\"}, {\"key\": \"B\", \"text\": \"比喻+对偶\"}, {\"key\": \"C\", \"text\": \"借代\"}, {\"key\": \"D\", \"text\": \"夸张\"}]', 'B', '用春蚕和蜡炬比喻对爱的忠贞，两句对仗构成对偶', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.056', NULL, '2026-08-09 02:30:25.056', NULL);
INSERT INTO `edu_question` VALUES (3310000000000007, 1300000000000001, 2310000000000005, 'single', 4, '\"先天下之忧而忧，后天下之乐而乐\"表达了什么情感？', '[{\"key\": \"A\", \"text\": \"个人名利\"}, {\"key\": \"B\", \"text\": \"忧国忧民的家国情怀\"}, {\"key\": \"C\", \"text\": \"隐居田园\"}, {\"key\": \"D\", \"text\": \"功成名就的豪情\"}]', 'B', '范仲淹表达了以天下为己任的忧国忧民的政治抱负', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.056', NULL, '2026-08-09 02:30:25.056', NULL);
INSERT INTO `edu_question` VALUES (3310000000000008, 1300000000000001, 2310000000000006, 'single', 4, '律诗中，下列哪项是平声字？', '[{\"key\": \"A\", \"text\": \"入声字（如\'得\'）\"}, {\"key\": \"B\", \"text\": \"阴平和阳平\"}, {\"key\": \"C\", \"text\": \"上声字（如\'好\'）\"}, {\"key\": \"D\", \"text\": \"去声字（如\'去\'）\"}]', 'B', '普通话中，阴平（第一声）和阳平（第二声）是平声', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.056', NULL, '2026-08-09 02:30:25.056', NULL);
INSERT INTO `edu_question` VALUES (3310000000000009, 1300000000000001, 2310000000000006, 'single', 4, '五言律诗每句有几个字？', '[{\"key\": \"A\", \"text\": \"5个\"}, {\"key\": \"B\", \"text\": \"7个\"}, {\"key\": \"C\", \"text\": \"4个\"}, {\"key\": \"D\", \"text\": \"6个\"}]', 'A', '五言律诗每句5个字，共8句', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.056', NULL, '2026-08-09 02:30:25.056', NULL);
INSERT INTO `edu_question` VALUES (3320000000000001, 1300000000000002, 2320000000000004, 'single', 3, '函数 f(x) = x² 的奇偶性是？', '[{\"key\": \"A\", \"text\": \"奇函数\"}, {\"key\": \"B\", \"text\": \"偶函数\"}, {\"key\": \"C\", \"text\": \"非奇非偶\"}, {\"key\": \"D\", \"text\": \"既奇又偶\"}]', 'B', 'f(-x)=(-x)²=x²=f(x)，满足偶函数定义', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.832', NULL, '2026-08-09 01:14:58.832', NULL);
INSERT INTO `edu_question` VALUES (3320000000000002, 1300000000000002, 2320000000000005, 'single', 3, '函数 y = √(4 - x²) 的值域是？', '[{\"key\": \"A\", \"text\": \"[-2, 2]\"}, {\"key\": \"B\", \"text\": \"[0, 2]\"}, {\"key\": \"C\", \"text\": \"(0, 2)\"}, {\"key\": \"D\", \"text\": \"[-2, 0]\"}]', 'B', '4-x²∈[0,4]，故y=√(4-x²)∈[0,2]', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.832', NULL, '2026-08-09 01:14:58.832', NULL);
INSERT INTO `edu_question` VALUES (3320000000000003, 1300000000000002, 2320000000000006, 'single', 4, '函数 f(x) = x³ 的导数是？', '[{\"key\": \"A\", \"text\": \"3x\"}, {\"key\": \"B\", \"text\": \"3x²\"}, {\"key\": \"C\", \"text\": \"x²\"}, {\"key\": \"D\", \"text\": \"2x³\"}]', 'B', '幂函数求导：(xⁿ)′= nxⁿ⁻¹，故(x³)′=3x²', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.832', NULL, '2026-08-09 01:14:58.832', NULL);
INSERT INTO `edu_question` VALUES (3320000000000004, 1300000000000002, 2320000000000006, 'single', 4, '若 f(x) = sin(x)，则 f′(π/2) = ？', '[{\"key\": \"A\", \"text\": \"0\"}, {\"key\": \"B\", \"text\": \"1\"}, {\"key\": \"C\", \"text\": \"-1\"}, {\"key\": \"D\", \"text\": \"π/2\"}]', 'A', 'f′(x)=cos(x)，f′(π/2)=cos(π/2)=0', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.832', NULL, '2026-08-09 01:14:58.832', NULL);
INSERT INTO `edu_question` VALUES (3320000000000005, 1300000000000002, 2320000000000004, 'single', 3, '函数 f(x) = x³ 的奇偶性是？', '[{\"key\": \"A\", \"text\": \"偶函数\"}, {\"key\": \"B\", \"text\": \"奇函数\"}, {\"key\": \"C\", \"text\": \"非奇非偶\"}, {\"key\": \"D\", \"text\": \"既奇又偶\"}]', 'B', 'f(-x)=(-x)³=-x³=-f(x)，满足奇函数定义', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.071', NULL, '2026-08-09 02:30:25.071', NULL);
INSERT INTO `edu_question` VALUES (3320000000000006, 1300000000000002, 2320000000000004, 'single', 3, '函数 y = x² 在哪个区间上单调递增？', '[{\"key\": \"A\", \"text\": \"(-∞, +∞)\"}, {\"key\": \"B\", \"text\": \"(-∞, 0)\"}, {\"key\": \"C\", \"text\": \"[0, +∞)\"}, {\"key\": \"D\", \"text\": \"[-1, 1]\"}]', 'C', 'y=x²是偶函数，在[0,+∞)单调递增，在(-∞,0]单调递减', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.071', NULL, '2026-08-09 02:30:25.071', NULL);
INSERT INTO `edu_question` VALUES (3320000000000007, 1300000000000002, 2320000000000005, 'single', 3, '函数 y = 2x + 1（x∈[0,3]）的值域是？', '[{\"key\": \"A\", \"text\": \"[1, 7]\"}, {\"key\": \"B\", \"text\": \"[0, 6]\"}, {\"key\": \"C\", \"text\": \"(1, 7)\"}, {\"key\": \"D\", \"text\": \"[2, 7]\"}]', 'A', 'x=0时y=1，x=3时y=7，线性函数，值域[1,7]', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.071', NULL, '2026-08-09 02:30:25.071', NULL);
INSERT INTO `edu_question` VALUES (3320000000000008, 1300000000000002, 2320000000000005, 'single', 3, '函数 y = x² - 2x + 3 的最小值是？', '[{\"key\": \"A\", \"text\": \"2\"}, {\"key\": \"B\", \"text\": \"3\"}, {\"key\": \"C\", \"text\": \"1\"}, {\"key\": \"D\", \"text\": \"0\"}]', 'A', '配方：y=(x-1)²+2，顶点(1,2)，最小值为2', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.071', NULL, '2026-08-09 02:30:25.071', NULL);
INSERT INTO `edu_question` VALUES (3320000000000009, 1300000000000002, 2320000000000006, 'single', 4, '函数 f(x) = e^x 的导数是？', '[{\"key\": \"A\", \"text\": \"xe^(x-1)\"}, {\"key\": \"B\", \"text\": \"e^x\"}, {\"key\": \"C\", \"text\": \"e^(x-1)\"}, {\"key\": \"D\", \"text\": \"1/e^x\"}]', 'B', '指数函数e^x的导数仍然是e^x，这是其特殊性', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.071', NULL, '2026-08-09 02:30:25.071', NULL);
INSERT INTO `edu_question` VALUES (3320000000000010, 1300000000000002, 2320000000000006, 'single', 4, 'f(x) = ln(x) 的导数是？', '[{\"key\": \"A\", \"text\": \"1/x\"}, {\"key\": \"B\", \"text\": \"ln(x)\"}, {\"key\": \"C\", \"text\": \"x\"}, {\"key\": \"D\", \"text\": \"1\"}]', 'A', '对数函数ln(x)的导数是1/x（x>0）', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.071', NULL, '2026-08-09 02:30:25.071', NULL);
INSERT INTO `edu_question` VALUES (3330000000000001, 1300000000000003, 2330000000000004, 'single', 3, 'The book ___ I borrowed yesterday is very interesting. (限制性定语从句)', '[{\"key\": \"A\", \"text\": \"who\"}, {\"key\": \"B\", \"text\": \"which\"}, {\"key\": \"C\", \"text\": \"whom\"}, {\"key\": \"D\", \"text\": \"whose\"}]', 'B', '先行词是book（物），用which或that引导定语从句', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.844', NULL, '2026-08-09 01:14:58.844', NULL);
INSERT INTO `edu_question` VALUES (3330000000000002, 1300000000000003, 2330000000000005, 'single', 4, 'My sister, ___ works in a hospital, is coming to visit me.', '[{\"key\": \"A\", \"text\": \"that\"}, {\"key\": \"B\", \"text\": \"who\"}, {\"key\": \"C\", \"text\": \"which\"}, {\"key\": \"D\", \"text\": \"whom\"}]', 'B', '非限制性定语从句，先行词是人，用who', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.844', NULL, '2026-08-09 01:14:58.844', NULL);
INSERT INTO `edu_question` VALUES (3330000000000003, 1300000000000003, 2330000000000006, 'single', 4, 'If I ___ you, I would study harder.', '[{\"key\": \"A\", \"text\": \"am\"}, {\"key\": \"B\", \"text\": \"was\"}, {\"key\": \"C\", \"text\": \"were\"}, {\"key\": \"D\", \"text\": \"be\"}]', 'C', '条件虚拟语气中，主语无论是什么，be动词一律用were', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.844', NULL, '2026-08-09 01:14:58.844', NULL);
INSERT INTO `edu_question` VALUES (3330000000000004, 1300000000000003, 2330000000000004, 'single', 3, 'The man ___ you met yesterday is my teacher.', '[{\"key\": \"A\", \"text\": \"which\"}, {\"key\": \"B\", \"text\": \"who\"}, {\"key\": \"C\", \"text\": \"whom\"}, {\"key\": \"D\", \"text\": \"whose\"}]', 'C', '先行词是人，作met的宾语，用whom（宾格）', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.085', NULL, '2026-08-09 02:30:25.085', NULL);
INSERT INTO `edu_question` VALUES (3330000000000005, 1300000000000003, 2330000000000004, 'single', 3, 'The city ___ I was born is very beautiful.', '[{\"key\": \"A\", \"text\": \"which\"}, {\"key\": \"B\", \"text\": \"that\"}, {\"key\": \"C\", \"text\": \"where\"}, {\"key\": \"D\", \"text\": \"when\"}]', 'C', '先行词是地点city，在从句中作地点状语，用where', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.085', NULL, '2026-08-09 02:30:25.085', NULL);
INSERT INTO `edu_question` VALUES (3330000000000006, 1300000000000003, 2330000000000005, 'single', 4, 'My father, ___ is a doctor, works in a big hospital.', '[{\"key\": \"A\", \"text\": \"that\"}, {\"key\": \"B\", \"text\": \"which\"}, {\"key\": \"C\", \"text\": \"who\"}, {\"key\": \"D\", \"text\": \"whom\"}]', 'C', '非限制性定语从句，先行词是人，用who（主格）', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.085', NULL, '2026-08-09 02:30:25.085', NULL);
INSERT INTO `edu_question` VALUES (3330000000000007, 1300000000000003, 2330000000000005, 'single', 4, 'She passed the exam, ___ surprised everyone.', '[{\"key\": \"A\", \"text\": \"that\"}, {\"key\": \"B\", \"text\": \"which\"}, {\"key\": \"C\", \"text\": \"who\"}, {\"key\": \"D\", \"text\": \"what\"}]', 'B', '以逗号分隔，指代整件事，用which引导非限制性定语从句', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.085', NULL, '2026-08-09 02:30:25.085', NULL);
INSERT INTO `edu_question` VALUES (3330000000000008, 1300000000000003, 2330000000000006, 'single', 4, 'If he ___ harder, he would pass the exam.', '[{\"key\": \"A\", \"text\": \"studies\"}, {\"key\": \"B\", \"text\": \"studied\"}, {\"key\": \"C\", \"text\": \"will study\"}, {\"key\": \"D\", \"text\": \"has studied\"}]', 'B', '与现在事实相反的虚拟语气，条件句谓语用过去式', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.085', NULL, '2026-08-09 02:30:25.085', NULL);
INSERT INTO `edu_question` VALUES (3330000000000009, 1300000000000003, 2330000000000006, 'single', 4, 'If I had known the answer, I ___ you.', '[{\"key\": \"A\", \"text\": \"would tell\"}, {\"key\": \"B\", \"text\": \"would have told\"}, {\"key\": \"C\", \"text\": \"will tell\"}, {\"key\": \"D\", \"text\": \"had told\"}]', 'B', '与过去事实相反的虚拟，主句用would have done', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.085', NULL, '2026-08-09 02:30:25.085', NULL);
INSERT INTO `edu_question` VALUES (3340000000000001, 1300000000000004, 2340000000000004, 'single', 3, '质量 2kg 的物体，受到 10N 的合力，其加速度是？', '[{\"key\": \"A\", \"text\": \"5 m/s²\"}, {\"key\": \"B\", \"text\": \"20 m/s²\"}, {\"key\": \"C\", \"text\": \"8 m/s²\"}, {\"key\": \"D\", \"text\": \"12 m/s²\"}]', 'A', '牛顿第二定律 a = F/m = 10/2 = 5 m/s²', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.857', NULL, '2026-08-09 01:14:58.857', NULL);
INSERT INTO `edu_question` VALUES (3340000000000002, 1300000000000004, 2340000000000005, 'single', 3, '静摩擦力的最大值与哪个因素有关？', '[{\"key\": \"A\", \"text\": \"物体的速度\"}, {\"key\": \"B\", \"text\": \"接触面的粗糙程度和正压力\"}, {\"key\": \"C\", \"text\": \"物体的质量\"}, {\"key\": \"D\", \"text\": \"接触面积的大小\"}]', 'B', '最大静摩擦力 f = μN，与正压力N和动摩擦因数μ有关', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.857', NULL, '2026-08-09 01:14:58.857', NULL);
INSERT INTO `edu_question` VALUES (3340000000000003, 1300000000000004, 2340000000000006, 'single', 4, '以初速度 v₀ 水平抛出的物体，经过时间 t 后，竖直位移为？', '[{\"key\": \"A\", \"text\": \"v₀t\"}, {\"key\": \"B\", \"text\": \"½gt²\"}, {\"key\": \"C\", \"text\": \"gt\"}, {\"key\": \"D\", \"text\": \"v₀t + ½gt²\"}]', 'B', '水平抛体竖直方向自由落体，y = ½gt²', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.857', NULL, '2026-08-09 01:14:58.857', NULL);
INSERT INTO `edu_question` VALUES (3340000000000004, 1300000000000004, 2340000000000004, 'single', 3, '若物体加速度为0，则物体所受合力为？', '[{\"key\": \"A\", \"text\": \"不存在\"}, {\"key\": \"B\", \"text\": \"0\"}, {\"key\": \"C\", \"text\": \"与速度相等\"}, {\"key\": \"D\", \"text\": \"等于重力\"}]', 'B', '由牛顿第二定律F=ma，a=0则F=0，即合力为零', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.097', NULL, '2026-08-09 02:30:25.097', NULL);
INSERT INTO `edu_question` VALUES (3340000000000005, 1300000000000004, 2340000000000004, 'single', 3, '质量为5kg的物体，加速度为3m/s²，合力大小是？', '[{\"key\": \"A\", \"text\": \"1.67N\"}, {\"key\": \"B\", \"text\": \"15N\"}, {\"key\": \"C\", \"text\": \"8N\"}, {\"key\": \"D\", \"text\": \"2N\"}]', 'B', 'F=ma=5×3=15N', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.097', NULL, '2026-08-09 02:30:25.097', NULL);
INSERT INTO `edu_question` VALUES (3340000000000006, 1300000000000004, 2340000000000005, 'single', 3, '下列哪种情况下，摩擦力为零？', '[{\"key\": \"A\", \"text\": \"物体在粗糙面上运动\"}, {\"key\": \"B\", \"text\": \"两接触面之间没有相对运动趋势\"}, {\"key\": \"C\", \"text\": \"物体静止在斜面上\"}, {\"key\": \"D\", \"text\": \"物体做匀速运动\"}]', 'B', '没有相对运动趋势，就不存在摩擦力', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.097', NULL, '2026-08-09 02:30:25.097', NULL);
INSERT INTO `edu_question` VALUES (3340000000000007, 1300000000000004, 2340000000000005, 'single', 3, '动摩擦力的方向？', '[{\"key\": \"A\", \"text\": \"与重力方向相同\"}, {\"key\": \"B\", \"text\": \"与物体运动方向相同\"}, {\"key\": \"C\", \"text\": \"与物体运动方向相反\"}, {\"key\": \"D\", \"text\": \"竖直向下\"}]', 'C', '动摩擦力方向与相对运动方向相反，阻碍相对运动', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.097', NULL, '2026-08-09 02:30:25.097', NULL);
INSERT INTO `edu_question` VALUES (3340000000000008, 1300000000000004, 2340000000000006, 'single', 4, '平抛运动的水平分运动是？', '[{\"key\": \"A\", \"text\": \"匀加速运动\"}, {\"key\": \"B\", \"text\": \"匀减速运动\"}, {\"key\": \"C\", \"text\": \"匀速直线运动\"}, {\"key\": \"D\", \"text\": \"自由落体\"}]', 'C', '水平方向无外力，做匀速直线运动', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.097', NULL, '2026-08-09 02:30:25.097', NULL);
INSERT INTO `edu_question` VALUES (3340000000000009, 1300000000000004, 2340000000000006, 'single', 4, '抛体运动的竖直分运动是？', '[{\"key\": \"A\", \"text\": \"匀速直线运动\"}, {\"key\": \"B\", \"text\": \"匀减速运动\"}, {\"key\": \"C\", \"text\": \"自由落体运动\"}, {\"key\": \"D\", \"text\": \"圆周运动\"}]', 'C', '竖直方向只受重力，做自由落体运动', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.097', NULL, '2026-08-09 02:30:25.097', NULL);
INSERT INTO `edu_question` VALUES (3350000000000001, 1300000000000005, 2350000000000004, 'single', 3, '在 2Fe + 3Cl₂ → 2FeCl₃ 中，Fe 的化合价变化是？', '[{\"key\": \"A\", \"text\": \"0→+2\"}, {\"key\": \"B\", \"text\": \"0→+3\"}, {\"key\": \"C\", \"text\": \"+2→+3\"}, {\"key\": \"D\", \"text\": \"+3→0\"}]', 'B', 'Fe从单质0价→FeCl₃中+3价，被氧化', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.869', NULL, '2026-08-09 01:14:58.869', NULL);
INSERT INTO `edu_question` VALUES (3350000000000002, 1300000000000005, 2350000000000005, 'single', 4, '氧化还原方程式中，化合价升高的元素被？', '[{\"key\": \"A\", \"text\": \"还原\"}, {\"key\": \"B\", \"text\": \"氧化\"}, {\"key\": \"C\", \"text\": \"中和\"}, {\"key\": \"D\", \"text\": \"取代\"}]', 'B', '化合价升高→失去电子→被氧化（是还原剂）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.869', NULL, '2026-08-09 01:14:58.869', NULL);
INSERT INTO `edu_question` VALUES (3350000000000003, 1300000000000005, 2350000000000006, 'single', 4, '增大压强，对可逆反应平衡的影响是？', '[{\"key\": \"A\", \"text\": \"向气体分子数增大方向移动\"}, {\"key\": \"B\", \"text\": \"向气体分子数减小方向移动\"}, {\"key\": \"C\", \"text\": \"不影响平衡\"}, {\"key\": \"D\", \"text\": \"平衡常数增大\"}]', 'B', '增大压强，平衡向减小气体体积（分子数减小）的方向移动（勒夏特列原理）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.869', NULL, '2026-08-09 01:14:58.869', NULL);
INSERT INTO `edu_question` VALUES (3350000000000004, 1300000000000005, 2350000000000004, 'single', 3, '在反应中，失去电子的物质叫做？', '[{\"key\": \"A\", \"text\": \"氧化剂\"}, {\"key\": \"B\", \"text\": \"还原剂\"}, {\"key\": \"C\", \"text\": \"催化剂\"}, {\"key\": \"D\", \"text\": \"生成物\"}]', 'B', '失去电子→化合价升高→被氧化→该物质是还原剂', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.110', NULL, '2026-08-09 02:30:25.110', NULL);
INSERT INTO `edu_question` VALUES (3350000000000005, 1300000000000005, 2350000000000004, 'single', 3, 'Zn + CuSO₄ → ZnSO₄ + Cu 中，被还原的是？', '[{\"key\": \"A\", \"text\": \"Zn\"}, {\"key\": \"B\", \"text\": \"SO₄²⁻\"}, {\"key\": \"C\", \"text\": \"Cu²⁺\"}, {\"key\": \"D\", \"text\": \"ZnSO₄\"}]', 'C', 'Cu²⁺得到电子变为Cu，化合价降低，被还原', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.110', NULL, '2026-08-09 02:30:25.110', NULL);
INSERT INTO `edu_question` VALUES (3350000000000006, 1300000000000005, 2350000000000005, 'single', 4, '配平 H₂ + O₂ → H₂O 后，系数是？', '[{\"key\": \"A\", \"text\": \"1, 1, 1\"}, {\"key\": \"B\", \"text\": \"2, 1, 2\"}, {\"key\": \"C\", \"text\": \"1, 1, 2\"}, {\"key\": \"D\", \"text\": \"2, 2, 2\"}]', 'B', '2H₂ + O₂ → 2H₂O，氢气系数2，氧气系数1，水系数2', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.110', NULL, '2026-08-09 02:30:25.110', NULL);
INSERT INTO `edu_question` VALUES (3350000000000007, 1300000000000005, 2350000000000005, 'single', 4, '配平时，化合价升高总数与降低总数的关系是？', '[{\"key\": \"A\", \"text\": \"升高>降低\"}, {\"key\": \"B\", \"text\": \"升高=降低\"}, {\"key\": \"C\", \"text\": \"升高<降低\"}, {\"key\": \"D\", \"text\": \"无规律\"}]', 'B', '氧化还原反应中，得失电子总数相等，即化合价升高=降低', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.110', NULL, '2026-08-09 02:30:25.110', NULL);
INSERT INTO `edu_question` VALUES (3350000000000008, 1300000000000005, 2350000000000006, 'single', 4, '升高温度，对可逆反应平衡的影响是？', '[{\"key\": \"A\", \"text\": \"向放热方向移动\"}, {\"key\": \"B\", \"text\": \"向吸热方向移动\"}, {\"key\": \"C\", \"text\": \"平衡不移动\"}, {\"key\": \"D\", \"text\": \"平衡常数不变\"}]', 'B', '升温，平衡向吸热（正向/逆向取决于反应热）方向移动', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.110', NULL, '2026-08-09 02:30:25.110', NULL);
INSERT INTO `edu_question` VALUES (3350000000000009, 1300000000000005, 2350000000000006, 'single', 4, '增大反应物浓度，平衡如何移动？', '[{\"key\": \"A\", \"text\": \"向逆反应方向移动\"}, {\"key\": \"B\", \"text\": \"向正反应方向移动\"}, {\"key\": \"C\", \"text\": \"不移动\"}, {\"key\": \"D\", \"text\": \"平衡常数增大\"}]', 'B', '增大反应物浓度，平衡向正反应方向移动（勒夏特列原理）', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.110', NULL, '2026-08-09 02:30:25.110', NULL);
INSERT INTO `edu_question` VALUES (3360000000000001, 1300000000000006, 2360000000000004, 'single', 3, '孟德尔分离定律的实质是？', '[{\"key\": \"A\", \"text\": \"性状的分离\"}, {\"key\": \"B\", \"text\": \"等位基因随同源染色体分开而分离\"}, {\"key\": \"C\", \"text\": \"杂合子自交后代比例为3:1\"}, {\"key\": \"D\", \"text\": \"显性基因遮蔽隐性基因\"}]', 'B', '分离定律实质：形成配子时等位基因随同源染色体分离', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.882', NULL, '2026-08-09 01:14:58.882', NULL);
INSERT INTO `edu_question` VALUES (3360000000000002, 1300000000000006, 2360000000000005, 'single', 4, 'Aa × Aa，后代中纯合子的比例是？', '[{\"key\": \"A\", \"text\": \"1/4\"}, {\"key\": \"B\", \"text\": \"1/2\"}, {\"key\": \"C\", \"text\": \"3/4\"}, {\"key\": \"D\", \"text\": \"1/3\"}]', 'B', '后代AA:Aa:aa=1:2:1，纯合子AA+aa=1/4+1/4=1/2', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.882', NULL, '2026-08-09 01:14:58.882', NULL);
INSERT INTO `edu_question` VALUES (3360000000000003, 1300000000000006, 2360000000000006, 'single', 4, 'DNA双螺旋结构中，碱基互补配对规则是？', '[{\"key\": \"A\", \"text\": \"A-T，G-C\"}, {\"key\": \"B\", \"text\": \"A-G，T-C\"}, {\"key\": \"C\", \"text\": \"A-C，T-G\"}, {\"key\": \"D\", \"text\": \"A-U，T-C\"}]', 'A', 'DNA碱基配对：腺嘌呤A与胸腺嘧啶T配对，鸟嘌呤G与胞嘧啶C配对', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.882', NULL, '2026-08-09 01:14:58.882', NULL);
INSERT INTO `edu_question` VALUES (3360000000000004, 1300000000000006, 2360000000000004, 'single', 3, '孟德尔自由组合定律适用于？', '[{\"key\": \"A\", \"text\": \"同一对等位基因\"}, {\"key\": \"B\", \"text\": \"位于非同源染色体上的非等位基因\"}, {\"key\": \"C\", \"text\": \"连锁基因\"}, {\"key\": \"D\", \"text\": \"所有基因\"}]', 'B', '自由组合定律适用于位于非同源染色体上的两对及以上等位基因', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.122', NULL, '2026-08-09 02:30:25.122', NULL);
INSERT INTO `edu_question` VALUES (3360000000000005, 1300000000000006, 2360000000000004, 'single', 3, 'F1 Aa 自交，后代比例为？', '[{\"key\": \"A\", \"text\": \"AA:Aa:aa = 1:2:1\"}, {\"key\": \"B\", \"text\": \"AA:Aa:aa = 3:0:1\"}, {\"key\": \"C\", \"text\": \"全为Aa\"}, {\"key\": \"D\", \"text\": \"AA:aa = 1:1\"}]', 'A', 'Aa×Aa → AA:Aa:aa = 1:2:1，表现型比3:1', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.122', NULL, '2026-08-09 02:30:25.122', NULL);
INSERT INTO `edu_question` VALUES (3360000000000006, 1300000000000006, 2360000000000005, 'single', 4, 'AaBb × AaBb 后代中，AABB的比例是？', '[{\"key\": \"A\", \"text\": \"1/4\"}, {\"key\": \"B\", \"text\": \"1/8\"}, {\"key\": \"C\", \"text\": \"1/16\"}, {\"key\": \"D\", \"text\": \"1/2\"}]', 'C', 'AA概率1/4，BB概率1/4，独立遗传：1/4×1/4=1/16', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.122', NULL, '2026-08-09 02:30:25.122', NULL);
INSERT INTO `edu_question` VALUES (3360000000000007, 1300000000000006, 2360000000000005, 'single', 4, '红花(RR)×白花(rr)，F2表现型比例是？', '[{\"key\": \"A\", \"text\": \"1:1\"}, {\"key\": \"B\", \"text\": \"3:1（红:白）\"}, {\"key\": \"C\", \"text\": \"全为红花\"}, {\"key\": \"D\", \"text\": \"1:2:1\"}]', 'B', 'F1为Rr（红花），F2: RR:Rr:rr = 1:2:1，红花:白花=3:1', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.122', NULL, '2026-08-09 02:30:25.122', NULL);
INSERT INTO `edu_question` VALUES (3360000000000008, 1300000000000006, 2360000000000006, 'single', 4, 'DNA的两条链之间通过什么连接？', '[{\"key\": \"A\", \"text\": \"共价键\"}, {\"key\": \"B\", \"text\": \"离子键\"}, {\"key\": \"C\", \"text\": \"氢键\"}, {\"key\": \"D\", \"text\": \"肽键\"}]', 'C', 'DNA双链之间的碱基对通过氢键连接（A-T间2个氢键，G-C间3个）', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.122', NULL, '2026-08-09 02:30:25.122', NULL);
INSERT INTO `edu_question` VALUES (3360000000000009, 1300000000000006, 2360000000000006, 'single', 4, 'DNA分子中，若A占20%，则G占多少？', '[{\"key\": \"A\", \"text\": \"20%\"}, {\"key\": \"B\", \"text\": \"30%\"}, {\"key\": \"C\", \"text\": \"40%\"}, {\"key\": \"D\", \"text\": \"60%\"}]', 'B', 'A=T=20%，所以G+C=60%，G=C=30%', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.122', NULL, '2026-08-09 02:30:25.122', NULL);
INSERT INTO `edu_question` VALUES (3410000000000001, 1400000000000001, 2410000000000004, 'single', 4, 'lim(n→∞) 1/n 的极限是？', '[{\"key\": \"A\", \"text\": \"∞\"}, {\"key\": \"B\", \"text\": \"1\"}, {\"key\": \"C\", \"text\": \"0\"}, {\"key\": \"D\", \"text\": \"不存在\"}]', 'C', '数列极限：当n趋于无穷大，1/n趋于0', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.895', NULL, '2026-08-09 01:14:58.895', NULL);
INSERT INTO `edu_question` VALUES (3410000000000002, 1400000000000001, 2410000000000005, 'single', 4, 'lim(x→0) sin(x)/x 的极限值是？', '[{\"key\": \"A\", \"text\": \"0\"}, {\"key\": \"B\", \"text\": \"1\"}, {\"key\": \"C\", \"text\": \"∞\"}, {\"key\": \"D\", \"text\": \"不存在\"}]', 'B', '重要极限：lim(x→0) sin(x)/x = 1', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.895', NULL, '2026-08-09 01:14:58.895', NULL);
INSERT INTO `edu_question` VALUES (3410000000000003, 1400000000000001, 2410000000000006, 'single', 5, '当 x→0 时，sin(x) 与 x 的关系是？', '[{\"key\": \"A\", \"text\": \"sin(x) 是 x 的高阶无穷小\"}, {\"key\": \"B\", \"text\": \"sin(x) 是 x 的等价无穷小\"}, {\"key\": \"C\", \"text\": \"sin(x) 与 x 无关\"}, {\"key\": \"D\", \"text\": \"sin(x) 是 x 的低阶无穷小\"}]', 'B', 'sin(x)~x（x→0），它们是等价无穷小', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.895', NULL, '2026-08-09 01:14:58.895', NULL);
INSERT INTO `edu_question` VALUES (3410000000000004, 1400000000000001, 2410000000000004, 'single', 4, 'lim(n→∞) (1 + 1/n)^n 等于？', '[{\"key\": \"A\", \"text\": \"1\"}, {\"key\": \"B\", \"text\": \"2\"}, {\"key\": \"C\", \"text\": \"e\"}, {\"key\": \"D\", \"text\": \"∞\"}]', 'C', '这是自然常数e的定义式，e≈2.718', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.135', NULL, '2026-08-09 02:30:25.135', NULL);
INSERT INTO `edu_question` VALUES (3410000000000005, 1400000000000001, 2410000000000004, 'single', 4, '数列 {(-1)^n} 的极限？', '[{\"key\": \"A\", \"text\": \"0\"}, {\"key\": \"B\", \"text\": \"1\"}, {\"key\": \"C\", \"text\": \"-1\"}, {\"key\": \"D\", \"text\": \"不存在\"}]', 'D', '(-1)^n在1和-1之间振荡，极限不存在', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.135', NULL, '2026-08-09 02:30:25.135', NULL);
INSERT INTO `edu_question` VALUES (3410000000000006, 1400000000000001, 2410000000000005, 'single', 4, 'lim(x→2)(x² - 4)/(x - 2) 等于？', '[{\"key\": \"A\", \"text\": \"0\"}, {\"key\": \"B\", \"text\": \"2\"}, {\"key\": \"C\", \"text\": \"4\"}, {\"key\": \"D\", \"text\": \"不存在\"}]', 'C', '因式分解：(x²-4)/(x-2)=(x+2)(x-2)/(x-2)=x+2，代入x=2得4', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.135', NULL, '2026-08-09 02:30:25.135', NULL);
INSERT INTO `edu_question` VALUES (3410000000000007, 1400000000000001, 2410000000000005, 'single', 4, 'lim(x→∞) (3x² + 2x)/(x² + 1) 等于？', '[{\"key\": \"A\", \"text\": \"0\"}, {\"key\": \"B\", \"text\": \"2\"}, {\"key\": \"C\", \"text\": \"3\"}, {\"key\": \"D\", \"text\": \"∞\"}]', 'C', '最高次项系数之比：3/1 = 3', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.135', NULL, '2026-08-09 02:30:25.135', NULL);
INSERT INTO `edu_question` VALUES (3410000000000008, 1400000000000001, 2410000000000006, 'single', 5, 'x→0 时，tan(x) 与哪个量等价无穷小？', '[{\"key\": \"A\", \"text\": \"x²\"}, {\"key\": \"B\", \"text\": \"x\"}, {\"key\": \"C\", \"text\": \"sin(x²)\"}, {\"key\": \"D\", \"text\": \"1/x\"}]', 'B', 'tan(x) ~ x（x→0），两者是等价无穷小', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.135', NULL, '2026-08-09 02:30:25.135', NULL);
INSERT INTO `edu_question` VALUES (3410000000000009, 1400000000000001, 2410000000000006, 'single', 5, 'x→0 时，1 - cos(x) 等价于？', '[{\"key\": \"A\", \"text\": \"x\"}, {\"key\": \"B\", \"text\": \"x²/2\"}, {\"key\": \"C\", \"text\": \"x²\"}, {\"key\": \"D\", \"text\": \"2x\"}]', 'B', '1-cos(x) ~ x²/2（x→0）是常用等价无穷小', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.135', NULL, '2026-08-09 02:30:25.135', NULL);
INSERT INTO `edu_question` VALUES (3420000000000001, 1400000000000002, 2420000000000004, 'single', 3, '\"bio-\" 这个词根的含义是？', '[{\"key\": \"A\", \"text\": \"生命\"}, {\"key\": \"B\", \"text\": \"光\"}, {\"key\": \"C\", \"text\": \"水\"}, {\"key\": \"D\", \"text\": \"地\"}]', 'A', '\"bio-\" 来自希腊语，含义为\"生命\"，如biology生物学', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.912', NULL, '2026-08-09 01:14:58.912', NULL);
INSERT INTO `edu_question` VALUES (3420000000000002, 1400000000000002, 2420000000000005, 'single', 4, '\"hypothesis\" 在学术英语中的含义是？', '[{\"key\": \"A\", \"text\": \"结论\"}, {\"key\": \"B\", \"text\": \"假设\"}, {\"key\": \"C\", \"text\": \"实验\"}, {\"key\": \"D\", \"text\": \"数据\"}]', 'B', '\"hypothesis\"=假设，是科学研究中待验证的命题', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.912', NULL, '2026-08-09 01:14:58.912', NULL);
INSERT INTO `edu_question` VALUES (3420000000000003, 1400000000000002, 2420000000000006, 'single', 4, '英文学术论文摘要（Abstract）的主要内容不包括？', '[{\"key\": \"A\", \"text\": \"研究目的\"}, {\"key\": \"B\", \"text\": \"研究方法\"}, {\"key\": \"C\", \"text\": \"个人简历\"}, {\"key\": \"D\", \"text\": \"主要结论\"}]', 'C', '摘要包括目的、方法、结果、结论，不包括作者个人信息', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.912', NULL, '2026-08-09 01:14:58.912', NULL);
INSERT INTO `edu_question` VALUES (3420000000000004, 1400000000000002, 2420000000000004, 'single', 3, '\"micro-\" 这个前缀的含义是？', '[{\"key\": \"A\", \"text\": \"大\"}, {\"key\": \"B\", \"text\": \"小/微\"}, {\"key\": \"C\", \"text\": \"多\"}, {\"key\": \"D\", \"text\": \"快\"}]', 'B', '\"micro-\"表示\"微小\"，如microscope显微镜、microbe微生物', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.147', NULL, '2026-08-09 02:30:25.147', NULL);
INSERT INTO `edu_question` VALUES (3420000000000005, 1400000000000002, 2420000000000004, 'single', 3, '\"pre-\" 这个前缀的含义是？', '[{\"key\": \"A\", \"text\": \"之后\"}, {\"key\": \"B\", \"text\": \"反对\"}, {\"key\": \"C\", \"text\": \"之前\"}, {\"key\": \"D\", \"text\": \"再次\"}]', 'C', '\"pre-\"表示\"在……之前\"，如preview预习、prevent预防', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.147', NULL, '2026-08-09 02:30:25.147', NULL);
INSERT INTO `edu_question` VALUES (3420000000000006, 1400000000000002, 2420000000000005, 'single', 4, '\"methodology\" 在学术英语中的含义是？', '[{\"key\": \"A\", \"text\": \"方法论/研究方法\"}, {\"key\": \"B\", \"text\": \"结论\"}, {\"key\": \"C\", \"text\": \"文献综述\"}, {\"key\": \"D\", \"text\": \"研究背景\"}]', 'A', '\"methodology\"是学术论文中常用词，指研究所用的方法和方法论', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.147', NULL, '2026-08-09 02:30:25.147', NULL);
INSERT INTO `edu_question` VALUES (3420000000000007, 1400000000000002, 2420000000000005, 'single', 4, '\"peer review\" 在学术语境中指？', '[{\"key\": \"A\", \"text\": \"导师评阅\"}, {\"key\": \"B\", \"text\": \"同行评审\"}, {\"key\": \"C\", \"text\": \"自我修改\"}, {\"key\": \"D\", \"text\": \"公开发表\"}]', 'B', '\"peer review\"是学术论文发表前由同领域专家评审的制度', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.147', NULL, '2026-08-09 02:30:25.147', NULL);
INSERT INTO `edu_question` VALUES (3420000000000008, 1400000000000002, 2420000000000006, 'single', 4, '学术摘要中，\"Results\"部分应包含？', '[{\"key\": \"A\", \"text\": \"研究背景与意义\"}, {\"key\": \"B\", \"text\": \"研究方法描述\"}, {\"key\": \"C\", \"text\": \"主要发现与数据\"}, {\"key\": \"D\", \"text\": \"参考文献\"}]', 'C', 'Results部分呈现研究的主要发现、数据和实验结果', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.147', NULL, '2026-08-09 02:30:25.147', NULL);
INSERT INTO `edu_question` VALUES (3420000000000009, 1400000000000002, 2420000000000006, 'single', 4, '英文学术论文摘要通常不超过多少词？', '[{\"key\": \"A\", \"text\": \"50词\"}, {\"key\": \"B\", \"text\": \"100词\"}, {\"key\": \"C\", \"text\": \"250词\"}, {\"key\": \"D\", \"text\": \"500词\"}]', 'C', '大多数期刊要求摘要在150-250词以内', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.147', NULL, '2026-08-09 02:30:25.147', NULL);
INSERT INTO `edu_question` VALUES (3430000000000001, 1400000000000003, 2430000000000004, 'single', 3, '两个点电荷距离变为原来的2倍，库仑力变为原来的？', '[{\"key\": \"A\", \"text\": \"2倍\"}, {\"key\": \"B\", \"text\": \"4倍\"}, {\"key\": \"C\", \"text\": \"1/2倍\"}, {\"key\": \"D\", \"text\": \"1/4倍\"}]', 'D', '库仑定律 F=kq₁q₂/r²，r变为2r，F变为1/4', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.925', NULL, '2026-08-09 01:14:58.925', NULL);
INSERT INTO `edu_question` VALUES (3430000000000002, 1400000000000003, 2430000000000005, 'single', 5, '高斯定理的表述是？', '[{\"key\": \"A\", \"text\": \"闭合曲面的电通量等于面内电荷总量除以ε₀\"}, {\"key\": \"B\", \"text\": \"电场线从正电荷出发到负电荷\"}, {\"key\": \"C\", \"text\": \"两点间电势差等于电场做的功\"}, {\"key\": \"D\", \"text\": \"电场强度与距离成正比\"}]', 'A', '高斯定理：∮E·dS = Q/ε₀，封闭面电通量等于内部总电量/ε₀', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.925', NULL, '2026-08-09 01:14:58.925', NULL);
INSERT INTO `edu_question` VALUES (3430000000000003, 1400000000000003, 2430000000000006, 'single', 4, '法拉第电磁感应定律：感应电动势大小与什么成正比？', '[{\"key\": \"A\", \"text\": \"磁场强度\"}, {\"key\": \"B\", \"text\": \"磁通量的变化率\"}, {\"key\": \"C\", \"text\": \"线圈匝数\"}, {\"key\": \"D\", \"text\": \"线圈面积\"}]', 'B', 'ε = -dΦ/dt，感应电动势与磁通量变化率成正比', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.925', NULL, '2026-08-09 01:14:58.925', NULL);
INSERT INTO `edu_question` VALUES (3430000000000004, 1400000000000003, 2430000000000004, 'single', 3, '库仑定律中，电场力与电荷量的关系是？', '[{\"key\": \"A\", \"text\": \"与两电荷量之积成反比\"}, {\"key\": \"B\", \"text\": \"与两电荷量之积成正比\"}, {\"key\": \"C\", \"text\": \"只与一个电荷有关\"}, {\"key\": \"D\", \"text\": \"与电荷量无关\"}]', 'B', 'F = kq₁q₂/r²，力与两个电荷量乘积成正比', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.159', NULL, '2026-08-09 02:30:25.159', NULL);
INSERT INTO `edu_question` VALUES (3430000000000005, 1400000000000003, 2430000000000004, 'single', 3, '两点电荷距离不变，其中一个电荷量变为原来的3倍，库仑力变为？', '[{\"key\": \"A\", \"text\": \"3倍\"}, {\"key\": \"B\", \"text\": \"9倍\"}, {\"key\": \"C\", \"text\": \"1/3倍\"}, {\"key\": \"D\", \"text\": \"6倍\"}]', 'A', 'F = kq₁q₂/r²，一个电荷量变3倍，F变3倍', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.159', NULL, '2026-08-09 02:30:25.159', NULL);
INSERT INTO `edu_question` VALUES (3430000000000006, 1400000000000003, 2430000000000005, 'single', 5, '均匀带电球壳外部的电场，与下列哪个等效？', '[{\"key\": \"A\", \"text\": \"无电场\"}, {\"key\": \"B\", \"text\": \"均匀电场\"}, {\"key\": \"C\", \"text\": \"等效为电荷集中在球心的点电荷产生的电场\"}, {\"key\": \"D\", \"text\": \"随距离线性变化\"}]', 'C', '由高斯定理，均匀带电球壳外部等效于点电荷场', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.159', NULL, '2026-08-09 02:30:25.159', NULL);
INSERT INTO `edu_question` VALUES (3430000000000007, 1400000000000003, 2430000000000005, 'single', 5, '均匀带电球壳内部的电场强度是？', '[{\"key\": \"A\", \"text\": \"最大\"}, {\"key\": \"B\", \"text\": \"与表面相同\"}, {\"key\": \"C\", \"text\": \"0\"}, {\"key\": \"D\", \"text\": \"向球心方向\"}]', 'C', '由高斯定理，均匀带电球壳内部电场为0', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.159', NULL, '2026-08-09 02:30:25.159', NULL);
INSERT INTO `edu_question` VALUES (3430000000000008, 1400000000000003, 2430000000000006, 'single', 4, '线圈匝数越多，感应电动势？', '[{\"key\": \"A\", \"text\": \"越小\"}, {\"key\": \"B\", \"text\": \"不变\"}, {\"key\": \"C\", \"text\": \"越大\"}, {\"key\": \"D\", \"text\": \"与匝数无关\"}]', 'C', 'ε = N·dΦ/dt，感应电动势与线圈匝数N成正比', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.159', NULL, '2026-08-09 02:30:25.159', NULL);
INSERT INTO `edu_question` VALUES (3430000000000009, 1400000000000003, 2430000000000006, 'single', 4, '楞次定律的本质是？', '[{\"key\": \"A\", \"text\": \"能量守恒\"}, {\"key\": \"B\", \"text\": \"感应电流产生的磁场阻碍引起感应的磁通量变化\"}, {\"key\": \"C\", \"text\": \"右手定则\"}, {\"key\": \"D\", \"text\": \"增大感应电流\"}]', 'B', '楞次定律：感应电流的方向使其产生的磁场阻碍原磁通量变化', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.159', NULL, '2026-08-09 02:30:25.159', NULL);
INSERT INTO `edu_question` VALUES (3440000000000001, 1400000000000004, 2440000000000004, 'single', 3, '链表相比数组的优势是？', '[{\"key\": \"A\", \"text\": \"随机访问快\"}, {\"key\": \"B\", \"text\": \"插入和删除操作效率高\"}, {\"key\": \"C\", \"text\": \"内存占用少\"}, {\"key\": \"D\", \"text\": \"查找效率高\"}]', 'B', '链表插入/删除O(1)，数组插入/删除需移动元素O(n)', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.937', NULL, '2026-08-09 01:14:58.937', NULL);
INSERT INTO `edu_question` VALUES (3440000000000002, 1400000000000004, 2440000000000005, 'single', 3, '栈（Stack）遵循的原则是？', '[{\"key\": \"A\", \"text\": \"先进先出（FIFO）\"}, {\"key\": \"B\", \"text\": \"先进后出（FILO）\"}, {\"key\": \"C\", \"text\": \"随机访问\"}, {\"key\": \"D\", \"text\": \"优先级访问\"}]', 'B', '栈是LIFO（Last In First Out）先进后出结构', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.937', NULL, '2026-08-09 01:14:58.937', NULL);
INSERT INTO `edu_question` VALUES (3440000000000003, 1400000000000004, 2440000000000006, 'single', 4, '二叉树的中序遍历顺序是？', '[{\"key\": \"A\", \"text\": \"根→左→右\"}, {\"key\": \"B\", \"text\": \"左→根→右\"}, {\"key\": \"C\", \"text\": \"左→右→根\"}, {\"key\": \"D\", \"text\": \"右→根→左\"}]', 'B', '中序遍历：左子树→根节点→右子树（对BST可得有序序列）', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.937', NULL, '2026-08-09 01:14:58.937', NULL);
INSERT INTO `edu_question` VALUES (3440000000000004, 1400000000000004, 2440000000000006, 'single', 4, '具有 n 个节点的完全二叉树，其高度是？', '[{\"key\": \"A\", \"text\": \"n\"}, {\"key\": \"B\", \"text\": \"n/2\"}, {\"key\": \"C\", \"text\": \"⌊log₂n⌋ + 1\"}, {\"key\": \"D\", \"text\": \"2n\"}]', 'C', '完全二叉树高度 h = ⌊log₂n⌋ + 1', NULL, NULL, 0, NULL, '2026-08-09 01:14:58.937', NULL, '2026-08-09 01:14:58.937', NULL);
INSERT INTO `edu_question` VALUES (3440000000000005, 1400000000000004, 2440000000000004, 'single', 3, '数组相比链表的优势是？', '[{\"key\": \"A\", \"text\": \"插入删除快\"}, {\"key\": \"B\", \"text\": \"随机访问快（O(1)）\"}, {\"key\": \"C\", \"text\": \"内存动态分配\"}, {\"key\": \"D\", \"text\": \"大小可变\"}]', 'B', '数组支持随机访问O(1)，链表访问需遍历O(n)', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.171', NULL, '2026-08-09 02:30:25.171', NULL);
INSERT INTO `edu_question` VALUES (3440000000000006, 1400000000000004, 2440000000000004, 'single', 3, '单链表在任意位置插入节点的时间复杂度是？', '[{\"key\": \"A\", \"text\": \"O(1)\"}, {\"key\": \"B\", \"text\": \"O(log n)\"}, {\"key\": \"C\", \"text\": \"O(n)\"}, {\"key\": \"D\", \"text\": \"O(n²)\"}]', 'A', '已知插入位置的指针时，链表插入操作是O(1)', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.171', NULL, '2026-08-09 02:30:25.171', NULL);
INSERT INTO `edu_question` VALUES (3440000000000007, 1400000000000004, 2440000000000005, 'single', 3, '队列（Queue）遵循的原则是？', '[{\"key\": \"A\", \"text\": \"先进后出（LIFO）\"}, {\"key\": \"B\", \"text\": \"先进先出（FIFO）\"}, {\"key\": \"C\", \"text\": \"优先级最高先出\"}, {\"key\": \"D\", \"text\": \"随机出队\"}]', 'B', '队列是FIFO（First In First Out）先进先出结构', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.171', NULL, '2026-08-09 02:30:25.171', NULL);
INSERT INTO `edu_question` VALUES (3440000000000008, 1400000000000004, 2440000000000005, 'single', 3, '用栈实现括号匹配时，遇到左括号应？', '[{\"key\": \"A\", \"text\": \"出栈\"}, {\"key\": \"B\", \"text\": \"入栈\"}, {\"key\": \"C\", \"text\": \"清空栈\"}, {\"key\": \"D\", \"text\": \"比较栈顶\"}]', 'B', '遇到左括号入栈，遇到右括号时与栈顶左括号匹配后出栈', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.171', NULL, '2026-08-09 02:30:25.171', NULL);
INSERT INTO `edu_question` VALUES (3440000000000009, 1400000000000004, 2440000000000006, 'single', 4, '二叉树的前序遍历顺序是？', '[{\"key\": \"A\", \"text\": \"左→根→右\"}, {\"key\": \"B\", \"text\": \"根→左→右\"}, {\"key\": \"C\", \"text\": \"左→右→根\"}, {\"key\": \"D\", \"text\": \"右→根→左\"}]', 'B', '前序遍历：根节点→左子树→右子树', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.171', NULL, '2026-08-09 02:30:25.171', NULL);
INSERT INTO `edu_question` VALUES (3440000000000010, 1400000000000004, 2440000000000006, 'single', 4, '一棵满二叉树有7个节点，其叶子节点数为？', '[{\"key\": \"A\", \"text\": \"3\"}, {\"key\": \"B\", \"text\": \"4\"}, {\"key\": \"C\", \"text\": \"5\"}, {\"key\": \"D\", \"text\": \"7\"}]', 'B', '满二叉树3层：第1层1个，第2层2个，第3层4个叶子，共7个节点，叶子4个', NULL, NULL, 0, NULL, '2026-08-09 02:30:25.171', NULL, '2026-08-09 02:30:25.171', NULL);
INSERT INTO `edu_question` VALUES (344788301577850880, 1100000000000001, 2110000000000004, 'multi', 3, '以下哪些是汉语拼音中的声母？（ ）', '[{\"key\": \"A\", \"text\": \"b\"}, {\"key\": \"B\", \"text\": \"d\"}, {\"key\": \"C\", \"text\": \"m\"}, {\"key\": \"D\", \"text\": \"a\"}]', 'ABC', '汉语拼音中的声母包括b, d, m等，而a是韵母。', NULL, NULL, 0, 1, '2026-08-09 18:25:38.031', NULL, '2026-08-09 18:25:38.031', NULL);
INSERT INTO `edu_question` VALUES (344788301699485696, 1100000000000001, 2110000000000004, 'multi', 3, '下列哪个韵母与声母n组合成“an”音节？（ ）', '[{\"key\": \"A\", \"text\": \"en\"}, {\"key\": \"B\", \"text\": \"an\"}, {\"key\": \"C\", \"text\": \"ün\"}, {\"key\": \"D\", \"text\": \"ai\"}]', 'B', '韵母an与声母n组合成“an”音节，而en、ün、ai分别是其他音节的组成部分。', NULL, NULL, 0, 1, '2026-08-09 18:25:38.059', NULL, '2026-08-09 18:25:38.059', NULL);
INSERT INTO `edu_question` VALUES (344788301821120512, 1100000000000001, 2110000000000004, 'multi', 3, '以下哪个音节中包含复韵母？（ ）', '[{\"key\": \"A\", \"text\": \"zi\"}, {\"key\": \"B\", \"text\": \"gang\"}, {\"key\": \"C\", \"text\": \"he\"}, {\"key\": \"D\", \"text\": \"ni\"}]', 'B', '复韵母是指由两个或两个以上的元音组合而成的韵母，如gang中的ang。而zi、he、ni中的韵母分别是单元音韵母。', NULL, NULL, 0, 1, '2026-08-09 18:25:38.089', NULL, '2026-08-09 18:25:38.089', NULL);
INSERT INTO `edu_question` VALUES (345029000688701440, 1200000000000001, 2210000000000005, 'multi', 3, '下列各句中，词类活用错误的一项是：', '[{\"key\": \"A\", \"text\": \"他英勇地冲在最前面。\"}, {\"key\": \"B\", \"text\": \"战士们把敌人包围得水泄不通。\"}, {\"key\": \"C\", \"text\": \"这个城市的发展日新月异。\"}, {\"key\": \"D\", \"text\": \"他的脸色苍白，似乎病得很重。\"}]', 'A', '选项A中，\'英勇\'作为形容词用作副词，这是正确的。选项B中，\'包围\'是动词，用作使动用法，也是正确的。选项C中，\'发展\'是动词，用作名词，是正确的。选项D中，\'苍白\'是形容词，用作谓语，也是正确的。因此，没有错误的词类活用。此题选项可能存在误导性。', NULL, NULL, 0, 1, '2026-08-10 10:22:04.706', NULL, '2026-08-10 10:22:04.706', NULL);
INSERT INTO `edu_question` VALUES (345029000839696384, 1200000000000001, 2210000000000005, 'multi', 3, '下列句子中，\'以\'字的意义和用法相同的一项是：', '[{\"key\": \"A\", \"text\": \"以德服人\"}, {\"key\": \"B\", \"text\": \"以色侍人\"}, {\"key\": \"C\", \"text\": \"以理服人\"}, {\"key\": \"D\", \"text\": \"以武服人\"}]', 'A', '\'以\'在选项A和C中均为介词，表示凭借、用；在选项B和D中，\'以\'也是介词，但表示因为。因此，A和C的意义和用法相同。', NULL, NULL, 0, 1, '2026-08-10 10:22:04.762', NULL, '2026-08-10 10:22:04.762', NULL);
INSERT INTO `edu_question` VALUES (345029001049411584, 1200000000000001, 2210000000000005, 'multi', 3, '下列句子中，词类活用正确的一项是：', '[{\"key\": \"A\", \"text\": \"他的文章写得非常生动。\"}, {\"key\": \"B\", \"text\": \"这本书对提高我们的文学素养有很大帮助。\"}, {\"key\": \"C\", \"text\": \"她用歌声感染了在场的每一个人。\"}, {\"key\": \"D\", \"text\": \"这个小镇以山清水秀而闻名。\"}]', 'D', '选项A中，\'生动\'是形容词，用作谓语，这是正确的。选项B中，\'提高\'是动词，用作使动用法，也是正确的。选项C中，\'感染\'是动词，用作使动用法，是正确的。选项D中，\'闻名\'是形容词，用作谓语，也是正确的。因此，选项D中的词类活用是正确的。', NULL, NULL, 0, 1, '2026-08-10 10:22:04.794', NULL, '2026-08-10 10:22:04.794', NULL);
