INSERT INTO `sl_sys_oper_log` VALUES (344562266563284992, 'AI答疑', 0, '/chat/:session_id', 'POST', 1, 'admin', 1, '/api/edu/tutoring/chat/344529724242006016', '127.0.0.1', '内网IP', '{\"session_id\":\"344529724242006016\",\"content\":\"解释一下牛顿第二定律\"}', '{\"user_message_id\":\"344562212725198848\",\"ai_message_id\":\"344562266454233088\",\"reply\":\"牛顿第二定律是描述物体运动状态变化的基本定律。它告诉我们，一个物体的加速度与作用在它上面的合外力成正比，与它的质量成反比。用公式表示就是 F=ma，其中F是合外力，m是物体的质量，a是加速度。\\n\\n第1步：理解定律含义\\n牛顿第二定律说明了力、质量和加速度之间的关系。\\n\\n第2步：公式解析\\nF=ma 这个公式是定律的核心，它告诉我们力越大，加速度也越大；质量越大，加速度越小。\\n\\n第3步：核心知识点\\n- 力是改变物体运动状态的原因。\\n- 加速度是物体速度变化的快慢。\\n- 质量是物体惯性大小的量度。\\n\\n第4步：同类型练习题\\n选择题：一个物体在水平面上受到一个10N的力作用，质量为2kg，那么它的加速度是多少？\\nA. 5m/s²\\nB. 10m/s²\\nC. 20m/s²\\nD. 0m/s²\\n正确答案：A. 5m/s²（使用F=ma，a=F/m=10N/2kg=5m/s²）\"}', 0, '', 12858, '2026-08-09 03:27:27');
INSERT INTO `sl_sys_oper_log` VALUES (344562676267094016, '虚拟实验', 1, '/experiment/start', 'POST', 1, 'admin', 1, '/api/edu/tutoring/experiment/start', '127.0.0.1', '内网IP', '{\"experiment_id\":\"exp_lens\"}', '{\"session_id\":\"344562676124487680\",\"experiment\":{\"id\":\"exp_lens\",\"subject\":\"物理\",\"name\":\"凸透镜成像规律\",\"goal\":\"探究物距与像距关系，理解成像原理\",\"steps\":\"放置光源→调节物距→观察像的位置与大小→记录数据→分析规律\"},\"intro_message\":\"欢迎进行【凸透镜成像规律】虚拟实验！\\n\\n实验目的：探究物距与像距关系，理解成像原理\\n\\n实验步骤概览：放置光源→调节物距→观察像的位置与大小→记录数据→分析规律\\n\\n你可以随时向我提问操作规范、现象原理或安全注意事项。请问你准备从哪一步开始？\"}', 0, '', 33, '2026-08-09 03:29:05');
INSERT INTO `sl_sys_oper_log` VALUES (344562836850216960, '错题变式', 0, '/wrong-questions/:id/variant', 'POST', 1, 'admin', 1, '/api/edu/analytics/wrong-questions/344561291215638528/variant', '127.0.0.1', '内网IP', '{\"id\":\"344561291215638528\"}', '{\"variant\":{\"content\":\"They watch TV. 变一般疑问句：\",\"options_json\":[{\"key\":\"A\",\"text\":\"Do they watch TV?\"},{\"key\":\"B\",\"text\":\"Do they don\'t watch TV?\"},{\"key\":\"C\",\"text\":\"Don\'t they watch TV?\"},{\"key\":\"D\",\"text\":\"Do they watch not TV?\"}],\"answer\":\"A\",\"analysis\":\"一般疑问句的构成是在句子开头加上助动词或情态动词，并将主语和助动词或情态动词的顺序颠倒。正确的一般疑问句形式是\'Do they watch TV?\'。其他选项中的否定词位置错误或助动词使用不当。\"},\"from_cache\":false}', 0, '', 9847, '2026-08-09 03:29:43');
INSERT INTO `sl_sys_oper_log` VALUES (344562915392753664, '错题变式', 0, '/wrong-questions/:id/variant', 'POST', 1, 'admin', 1, '/api/edu/analytics/wrong-questions/344561291215638528/variant', '127.0.0.1', '内网IP', '{\"id\":\"344561291215638528\"}', '{\"variant\":{\"answer\":\"A\",\"content\":\"They watch TV. 变一般疑问句：\",\"analysis\":\"一般疑问句的构成是在句子开头加上助动词或情态动词，并将主语和助动词或情态动词的顺序颠倒。正确的一般疑问句形式是\'Do they watch TV?\'。其他选项中的否定词位置错误或助动词使用不当。\",\"options_json\":[{\"key\":\"A\",\"text\":\"Do they watch TV?\"},{\"key\":\"B\",\"text\":\"Do they don\'t watch TV?\"},{\"key\":\"C\",\"text\":\"Don\'t they watch TV?\"},{\"key\":\"D\",\"text\":\"Do they watch not TV?\"}]},\"from_cache\":true}', 0, '', 11, '2026-08-09 03:30:02');
