INSERT INTO `sl_sys_version` VALUES (10, 'v1.0.0', '2026-08-10', 'AI智能教育助手首发版', '【智能诊断评测】\n入学水平评测与知识点漏洞扫描，自适应难度算法动态调整题目难度\n5级掌握度分级（未学/了解/理解/应用/精通），评测报告含AI综合总结\n题库管理（管理员）：支持单选/多选/填空/主观题型，AI一键生成题目草稿\n\n【自适应学习引擎】\nAI根据薄弱知识点和前置依赖生成个性化今日学习计划\n知识图谱三维追踪（理解/记忆/应用），Canvas雷达图可视化\n智能题目推荐：从薄弱知识点精选练习题，排除近期已做题目\n\n【AI交互辅导工具】\n智能答疑：对话式提问，AI分步解析+同类题推荐\n主观题批改：AI返回得分、评语、改进建议和错误点列表\n口语评测：浏览器语音转录，AI三维评分（准确度/流利度/完整度）\n虚拟实验指导：预设6种理科实验，AI文字引导操作步骤\n\n【学情智能分析】\n实时学情看板与正确率/得分趋势折线图\n知识点掌握热力图，5级颜色直观展示\n学习预警系统：停滞/下降/低正确率自动检测，24小时防重推送\n错题本：自动收录错题，按错因分类筛选\n艾宾浩斯遗忘曲线复习提醒，AI生成变式练习题\n\n【长期记忆与成长记录】\n学习日历热力图，点击查看当天学习详情\n掌握度趋势折线图，按学科切换追踪进步\nAI交互历史统一搜索（问答+口语记录），支持关键词/类型/学科筛选\n全局学习统计：累计天数、连续天数、答题数、精通知识点数\n\n【学科与知识点管理】\n学科管理（管理员），支持小学/初中/高中/大学学段\n三层知识点树（章→节→知识点），支持前置依赖配置\n能力画像页：热力图+学科掌握度汇总+薄弱点列表\n\n【系统基础功能】\n用户注册/登录（JWT认证 + bcrypt加密）\nPC端明/暗主题切换，LocalStorage持久化\n系统通知公告与个人通知中心，60秒自动轮询\n用户反馈中心（缺陷/建议/其他），管理员可回复\n图片上传、版本记录、接口限流、安全响应头加固', '2026-08-10 10:44:47');
